INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000360','Apa definisi dasar dari petrofisika dalam konteks industri migas?','option','PFC000000001','Final Test','a:4:{i:0;s:75:"Studi tentang sifat fisik dan kimia batuan serta interaksinya dengan fluida";i:1;s:46:"Studi tentang pemetaan geologi bawah permukaan";i:2;s:41:"Analisis pergerakan tektonik lempeng bumi";i:3;s:45:"Studi mengenai metode pengeboran sumur minyak";}','','Studi tentang sifat fisik dan kimia batuan serta interaksinya dengan fluida','What is the basic definition of petrophysics in the oil and gas industry context?','a:4:{i:0;s:84:"The study of physical and chemical rock properties and their interaction with fluids";i:1;s:42:"The study of subsurface geological mapping";i:2;s:36:"Analysis of tectonic plate movements";i:3;s:38:"The study of oil well drilling methods";}','The study of physical and chemical rock properties and their interaction with fluids','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000361','Parameter apa yang paling utama ditentukan melalui analisis petrofisika untuk menghitung cadangan hidrokarbon?','multi','PFC000000001','Final Test','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:12:"Saturasi air";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:9:"Porositas";i:1;s:12:"Saturasi air";}','Which parameters are primary determined through petrophysical analysis to calculate hydrocarbon reserves?','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Water saturation";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:8:"Porosity";i:1;s:16:"Water saturation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000362','Apa perbedaan utama antara batuan reservoir terkonsolidasi dan tidak terkonsolidasi?','option','PFC000000001','Final Test','a:4:{i:0;s:31:"Tingkat sementasi antar butiran";i:1;s:12:"Warna batuan";i:2;s:21:"Kedalaman pengendapan";i:3;s:28:"Jenis mineral penyusun utama";}','','Tingkat sementasi antar butiran','What is the main difference between consolidated and unconsolidated reservoir rocks?','a:4:{i:0;s:36:"Degree of cementation between grains";i:1;s:10:"Rock color";i:2;s:16:"Deposition depth";i:3;s:33:"Type of main constituent minerals";}','Degree of cementation between grains','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000363','Apa yang dimaksud dengan porositas primer dalam batuan sedimen?','option','PFC000000001','Final Test','a:4:{i:0;s:51:"Porositas yang terbentuk selama pengendapan sedimen";i:1;s:48:"Porositas yang terbentuk akibat proses pelarutan";i:2;s:48:"Porositas yang terbentuk akibat rekahan tektonik";i:3;s:44:"Porositas yang terbentuk akibat dolomitisasi";}','','Porositas yang terbentuk selama pengendapan sedimen','What is meant by primary porosity in sedimentary rocks?','a:4:{i:0;s:42:"Porosity formed during sediment deposition";i:1;s:44:"Porosity formed due to dissolution processes";i:2;s:42:"Porosity formed due to tectonic fracturing";i:3;s:37:"Porosity formed due to dolomitization";}','Porosity formed during sediment deposition','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000364','Manakah dari berikut ini yang merupakan peran petrofisika dalam fase eksplorasi?','option','PFC000000001','Final Test','a:4:{i:0;s:51:"Evaluasi kualitas reservoir dan potensi hidrokarbon";i:1;s:32:"Perencanaan desain pipa penyalur";i:2;s:25:"Optimasi laju injeksi air";i:3;s:27:"Manajemen limbah pengeboran";}','','Evaluasi kualitas reservoir dan potensi hidrokarbon','Which of the following is a role of petrophysics in the exploration phase?','a:4:{i:0;s:57:"Evaluation of reservoir quality and hydrocarbon potential";i:1;s:24:"Pipeline design planning";i:2;s:37:"Optimization of water injection rates";i:3;s:25:"Drilling waste management";}','Evaluation of reservoir quality and hydrocarbon potential','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000365','Batuan reservoir dengan porositas 20% dikategorikan sebagai apa?','option','PFC000000001','Final Test','a:4:{i:0;s:11:"Baik (Good)";i:1;s:12:"Buruk (Poor)";i:2;s:24:"Sangat Buruk (Very Poor)";i:3;s:23:"Sangat Baik (Excellent)";}','','Baik (Good)','A reservoir rock with 20% porosity is categorized as what?','a:4:{i:0;s:4:"Good";i:1;s:4:"Poor";i:2;s:9:"Very Poor";i:3;s:9:"Excellent";}','Good','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000366','Apa yang terjadi pada porositas batuan jika tingkat sementasi meningkat?','option','PFC000000001','Final Test','a:4:{i:0;s:17:"Porositas menurun";i:1;s:19:"Porositas meningkat";i:2;s:15:"Porositas tetap";i:3;s:31:"Porositas menjadi tidak terukur";}','','Porositas menurun','What happens to rock porosity if the degree of cementation increases?','a:4:{i:0;s:18:"Porosity decreases";i:1;s:18:"Porosity increases";i:2;s:25:"Porosity remains constant";i:3;s:29:"Porosity becomes unmeasurable";}','Porosity decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000367','Data logging sumur mana yang paling umum digunakan untuk estimasi porositas secara langsung?','multi','PFC000000001','Final Test','a:4:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:13:"Gamma ray log";i:3;s:6:"SP log";}','','a:2:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";}','Which well logging data is most commonly used for direct porosity estimation?','a:4:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:13:"Gamma ray log";i:3;s:6:"SP log";}','a:2:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000368','Mengapa pasir lepas (unconsolidated sand) sering menjadi tantangan dalam produksi minyak?','option','PFC000000001','Final Test','a:4:{i:0;s:53:"Mudah terikut ke dalam lubang sumur (sand production)";i:1;s:41:"Memiliki permeabilitas yang sangat rendah";i:2;s:34:"Tidak dapat mengandung hidrokarbon";i:3;s:30:"Sangat sulit dilakukan logging";}','','Mudah terikut ke dalam lubang sumur (sand production)','Why is unconsolidated sand often a challenge in oil production?','a:4:{i:0;s:51:"Easily produced into the wellbore (sand production)";i:1;s:25:"Has very low permeability";i:2;s:27:"Cannot contain hydrocarbons";i:3;s:33:"Very difficult to perform logging";}','Easily produced into the wellbore (sand production)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000369','Apa hubungan antara ukuran butir dan porositas pada batuan sedimen yang terpilah baik (well-sorted)?','option','PFC000000001','Final Test','a:4:{i:0;s:27:"Tidak ada hubungan langsung";i:1;s:50:"Ukuran butir besar memiliki porositas lebih rendah";i:2;s:50:"Ukuran butir kecil memiliki porositas lebih tinggi";i:3;s:46:"Ukuran butir berbanding lurus dengan porositas";}','','Tidak ada hubungan langsung','What is the relationship between grain size and porosity in well-sorted sedimentary rocks?','a:4:{i:0;s:31:"There is no direct relationship";i:1;s:35:"Large grain size has lower porosity";i:2;s:36:"Small grain size has higher porosity";i:3;s:47:"Grain size is directly proportional to porosity";}','There is no direct relationship','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000370','Dalam konteks reservoir, apa yang dimaksud dengan ''Net Pay''?','option','PFC000000001','Final Test','a:4:{i:0;s:55:"Bagian reservoir yang produktif mengalirkan hidrokarbon";i:1;s:32:"Total ketebalan batuan reservoir";i:2;s:38:"Ketebalan zona shale di atas reservoir";i:3;s:39:"Volume air yang terperangkap dalam pori";}','','Bagian reservoir yang produktif mengalirkan hidrokarbon','In the reservoir context, what is meant by ''Net Pay''?','a:4:{i:0;s:71:"The portion of the reservoir that is productive in flowing hydrocarbons";i:1;s:30:"Total reservoir rock thickness";i:2;s:43:"Thickness of shale zone above the reservoir";i:3;s:32:"Volume of water trapped in pores";}','The portion of the reservoir that is productive in flowing hydrocarbons','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000371','Apa fungsi utama dari analisis core laboratorium dalam petrofisika?','option','PFC000000001','Final Test','a:4:{i:0;s:24:"Kalibrasi data log sumur";i:1;s:29:"Pembuatan desain casing sumur";i:2;s:25:"Estimasi biaya pengeboran";i:3;s:29:"Peningkatan tekanan reservoir";}','','Kalibrasi data log sumur','What is the main function of laboratory core analysis in petrophysics?','a:4:{i:0;s:28:"Calibration of well log data";i:1;s:21:"Designing well casing";i:2;s:25:"Estimating drilling costs";i:3;s:29:"Increasing reservoir pressure";}','Calibration of well log data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000372','Faktor apa saja yang memengaruhi porositas efektif?','multi','PFC000000001','Final Test','a:4:{i:0;s:16:"Geometri butiran";i:1;s:15:"Sortasi butiran";i:2;s:17:"Tingkat pemadatan";i:3;s:12:"Warna batuan";}','','a:3:{i:0;s:16:"Geometri butiran";i:1;s:15:"Sortasi butiran";i:2;s:17:"Tingkat pemadatan";}','Which factors influence effective porosity?','a:4:{i:0;s:14:"Grain geometry";i:1;s:13:"Grain sorting";i:2;s:17:"Compaction degree";i:3;s:10:"Rock color";}','a:3:{i:0;s:14:"Grain geometry";i:1;s:13:"Grain sorting";i:2;s:17:"Compaction degree";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000373','Apa perbedaan antara porositas total dan porositas efektif?','option','PFC000000001','Final Test','a:4:{i:0;s:59:"Porositas efektif hanya mencakup pori yang saling terhubung";i:1;s:40:"Porositas total lebih kecil dari efektif";i:2;s:50:"Porositas efektif tidak dipengaruhi oleh sementasi";i:3;s:28:"Tidak ada perbedaan keduanya";}','','Porositas efektif hanya mencakup pori yang saling terhubung','What is the difference between total porosity and effective porosity?','a:4:{i:0;s:53:"Effective porosity only includes interconnected pores";i:1;s:40:"Total porosity is smaller than effective";i:2;s:51:"Effective porosity is not influenced by cementation";i:3;s:35:"There is no difference between them";}','Effective porosity only includes interconnected pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000374','Mineral apa yang sering menyumbat pori-pori dan mengurangi porositas?','option','PFC000000001','Final Test','a:4:{i:0;s:14:"Lempung (Clay)";i:1;s:6:"Kuarsa";i:2;s:8:"Feldspar";i:3;s:6:"Zirkon";}','','Lempung (Clay)','Which mineral often clogs pores and reduces porosity?','a:4:{i:0;s:4:"Clay";i:1;s:6:"Quartz";i:2;s:8:"Feldspar";i:3;s:6:"Zircon";}','Clay','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000375','Mengapa petrofisika sangat krusial dalam tahap pengembangan lapangan (field development)?','option','PFC000000001','Final Test','a:4:{i:0;s:40:"Menentukan pola injeksi dan lokasi sumur";i:1;s:33:"Menentukan rute pengiriman minyak";i:2;s:22:"Mengatur pemasaran gas";i:3;s:36:"Mengelola hubungan dengan pemerintah";}','','Menentukan pola injeksi dan lokasi sumur','Why is petrophysics crucial in the field development stage?','a:4:{i:0;s:49:"Determining injection patterns and well locations";i:1;s:31:"Determining oil shipping routes";i:2;s:22:"Managing gas marketing";i:3;s:29:"Managing government relations";}','Determining injection patterns and well locations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000376','Apa yang dimaksud dengan ''vuggy porosity''?','option','PFC000000001','Final Test','a:4:{i:0;s:65:"Porositas yang terbentuk dari lubang-lubang besar hasil pelarutan";i:1;s:27:"Porositas antar butir pasir";i:2;s:29:"Porositas dalam retakan halus";i:3;s:40:"Porositas yang seragam di seluruh batuan";}','','Porositas yang terbentuk dari lubang-lubang besar hasil pelarutan','What is meant by ''vuggy porosity''?','a:4:{i:0;s:54:"Porosity formed from large cavities due to dissolution";i:1;s:27:"Intergranular sand porosity";i:2;s:30:"Porosity within fine fractures";i:3;s:36:"Uniform porosity throughout the rock";}','Porosity formed from large cavities due to dissolution','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000377','Manakah batuan yang umumnya memiliki porositas awal tinggi namun rentan terhadap kompaksi?','option','PFC000000001','Final Test','a:4:{i:0;s:33:"Pasir lepas (Unconsolidated sand)";i:1;s:21:"Batugamping kristalin";i:2;s:11:"Batuan beku";i:3;s:23:"Batupasir tersemen kuat";}','','Pasir lepas (Unconsolidated sand)','Which rock generally has high initial porosity but is susceptible to compaction?','a:4:{i:0;s:19:"Unconsolidated sand";i:1;s:21:"Crystalline limestone";i:2;s:12:"Igneous rock";i:3;s:27:"Strongly cemented sandstone";}','Unconsolidated sand','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000378','Apa dampak keberadaan rekahan (fractures) terhadap sifat petrofisika batuan?','option','PFC000000001','Final Test','a:4:{i:0;s:41:"Meningkatkan permeabilitas secara drastis";i:1;s:44:"Menurunkan porositas total secara signifikan";i:2;s:52:"Menghilangkan kemampuan batuan menyimpan hidrokarbon";i:3;s:35:"Tidak memiliki pengaruh sama sekali";}','','Meningkatkan permeabilitas secara drastis','What is the impact of fractures on rock petrophysical properties?','a:4:{i:0;s:34:"Drastically increases permeability";i:1;s:38:"Significantly decreases total porosity";i:2;s:51:"Eliminates the rock''s ability to store hydrocarbons";i:3;s:23:"Has no influence at all";}','Drastically increases permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000379','Apa peran utama dari data tekanan dalam studi petrofisika?','option','PFC000000001','Final Test','a:4:{i:0;s:34:"Menentukan kontak fluida (WOC/GOC)";i:1;s:27:"Mengukur berat jenis batuan";i:2;s:33:"Menghitung kecepatan rambat suara";i:3;s:32:"Mengidentifikasi mineral lempung";}','','Menentukan kontak fluida (WOC/GOC)','What is the main role of pressure data in petrophysical studies?','a:4:{i:0;s:36:"Determining fluid contacts (WOC/GOC)";i:1;s:22:"Measuring rock density";i:2;s:34:"Calculating acoustic wave velocity";i:3;s:25:"Identifying clay minerals";}','Determining fluid contacts (WOC/GOC)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000380','Apa definisi porositas efektif pada batuan reservoir?','option','PFC000000002','Final Test','a:4:{i:0;s:75:"Perbandingan volume pori yang saling berhubungan dengan volume total batuan";i:1;s:52:"Perbandingan volume total pori dengan volume butiran";i:2;s:63:"Perbandingan volume pori yang terisi fluida dengan volume total";i:3;s:71:"Perbandingan volume ruang pori yang tidak terhubung dengan volume total";}','','Perbandingan volume pori yang saling berhubungan dengan volume total batuan','What is the definition of effective porosity in reservoir rocks?','a:4:{i:0;s:60:"The ratio of interconnected pore volume to total rock volume";i:1;s:46:"The ratio of total pore volume to grain volume";i:2;s:53:"The ratio of fluid-filled pore volume to total volume";i:3;s:48:"The ratio of isolated pore space to total volume";}','The ratio of interconnected pore volume to total rock volume','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000381','Faktor apa saja yang memengaruhi permeabilitas batuan reservoir?','multi','PFC000000002','Final Test','a:4:{i:0;s:24:"Ukuran butir dan sortasi";i:1;s:22:"Kompaksi dan sementasi";i:2;s:12:"Saturasi air";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:24:"Ukuran butir dan sortasi";i:1;s:22:"Kompaksi dan sementasi";}','Which factors influence reservoir rock permeability?','a:4:{i:0;s:22:"Grain size and sorting";i:1;s:26:"Compaction and cementation";i:2;s:16:"Water saturation";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:22:"Grain size and sorting";i:1;s:26:"Compaction and cementation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000382','Hukum Darcy digunakan untuk menghitung laju alir fluida melalui media berpori dengan asumsi kondisi apa?','option','PFC000000002','Final Test','a:4:{i:0;s:70:"Aliran tunak (steady-state), fluida incompressible, dan aliran laminar";i:1;s:60:"Aliran tidak tunak, fluida compressible, dan aliran turbulen";i:2;s:56:"Aliran tunak, fluida incompressible, dan aliran turbulen";i:3;s:59:"Aliran tidak tunak, fluida compressible, dan aliran laminar";}','','Aliran tunak (steady-state), fluida incompressible, dan aliran laminar','Darcy''s Law is used to calculate fluid flow rate through porous media assuming which conditions?','a:4:{i:0;s:57:"Steady-state flow, incompressible fluid, and laminar flow";i:1;s:59:"Unsteady-state flow, compressible fluid, and turbulent flow";i:2;s:59:"Steady-state flow, incompressible fluid, and turbulent flow";i:3;s:57:"Unsteady-state flow, compressible fluid, and laminar flow";}','Steady-state flow, incompressible fluid, and laminar flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000383','Apa yang dimaksud dengan saturasi fluida (Sw)?','option','PFC000000002','Final Test','a:4:{i:0;s:39:"Fraksi volume pori yang terisi oleh air";i:1;s:47:"Perbandingan volume air terhadap volume butiran";i:2;s:46:"Fraksi volume air terhadap volume total batuan";i:3;s:41:"Jumlah air per satuan luas permukaan pori";}','','Fraksi volume pori yang terisi oleh air','What is meant by fluid saturation (Sw)?','a:4:{i:0;s:45:"The fraction of pore volume filled with water";i:1;s:41:"The ratio of water volume to grain volume";i:2;s:49:"The fraction of water volume to total rock volume";i:3;s:49:"The amount of water per unit of pore surface area";}','The fraction of pore volume filled with water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000384','Manakah pernyataan yang benar mengenai kompresibilitas batuan?','option','PFC000000002','Final Test','a:4:{i:0;s:50:"Perubahan volume pori per satuan perubahan tekanan";i:1;s:30:"Kemampuan fluida untuk ditekan";i:2;s:38:"Perubahan permeabilitas terhadap waktu";i:3;s:37:"Perubahan saturasi terhadap kedalaman";}','','Perubahan volume pori per satuan perubahan tekanan','Which statement is correct regarding rock compressibility?','a:4:{i:0;s:53:"The change in pore volume per unit change in pressure";i:1;s:39:"The ability of a fluid to be compressed";i:2;s:36:"The change in permeability over time";i:3;s:35:"The change in saturation with depth";}','The change in pore volume per unit change in pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000385','Alat laboratorium apa yang umum digunakan untuk mengukur porositas batuan core?','option','PFC000000002','Final Test','a:4:{i:0;s:18:"Porosimeter Helium";i:1;s:11:"Permeameter";i:2;s:10:"Centrifuge";i:3;s:43:"Mercury Injection Capillary Pressure (MICP)";}','','Porosimeter Helium','Which laboratory instrument is commonly used to measure core rock porosity?','a:4:{i:0;s:18:"Helium Porosimeter";i:1;s:11:"Permeameter";i:2;s:10:"Centrifuge";i:3;s:43:"Mercury Injection Capillary Pressure (MICP)";}','Helium Porosimeter','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000386','Mengapa permeabilitas absolut hanya bergantung pada geometri pori, bukan fluida?','option','PFC000000002','Final Test','a:4:{i:0;s:88:"Karena permeabilitas absolut didefinisikan untuk satu fase fluida yang mengisi 100% pori";i:1;s:47:"Karena fluida tidak memengaruhi struktur batuan";i:2;s:37:"Karena viskositas fluida dianggap nol";i:3;s:43:"Karena batuan bersifat homogen secara total";}','','Karena permeabilitas absolut didefinisikan untuk satu fase fluida yang mengisi 100% pori','Why does absolute permeability depend only on pore geometry, not the fluid?','a:4:{i:0;s:91:"Because absolute permeability is defined for a single fluid phase filling 100% of the pores";i:1;s:43:"Because fluids do not affect rock structure";i:2;s:45:"Because fluid viscosity is assumed to be zero";i:3;s:42:"Because the rock is completely homogeneous";}','Because absolute permeability is defined for a single fluid phase filling 100% of the pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000387','Jika sebuah batuan memiliki porositas primer dan sekunder, manakah istilah yang tepat untuk porositas totalnya?','option','PFC000000002','Final Test','a:4:{i:0;s:14:"Porositas dual";i:1;s:17:"Porositas efektif";i:2;s:16:"Porositas primer";i:3;s:23:"Porositas intragranular";}','','Porositas dual','If a rock has primary and secondary porosity, what is the correct term for its total porosity?','a:4:{i:0;s:13:"Dual porosity";i:1;s:18:"Effective porosity";i:2;s:16:"Primary porosity";i:3;s:22:"Intragranular porosity";}','Dual porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000388','Apa dampak peningkatan tekanan overburden terhadap porositas batuan?','option','PFC000000002','Final Test','a:4:{i:0;s:17:"Porositas menurun";i:1;s:19:"Porositas meningkat";i:2;s:15:"Porositas tetap";i:3;s:21:"Porositas menjadi nol";}','','Porositas menurun','What is the impact of increased overburden pressure on rock porosity?','a:4:{i:0;s:18:"Porosity decreases";i:1;s:18:"Porosity increases";i:2;s:25:"Porosity remains the same";i:3;s:21:"Porosity becomes zero";}','Porosity decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000389','Sebutkan parameter yang diperlukan untuk menghitung permeabilitas menggunakan Hukum Darcy.','multi','PFC000000002','Final Test','a:4:{i:0;s:13:"Laju alir (Q)";i:1;s:22:"Viskositas fluida (μ)";i:2;s:18:"Panjang sampel (L)";i:3;s:14:"Tipe sementasi";}','','a:3:{i:0;s:13:"Laju alir (Q)";i:1;s:22:"Viskositas fluida (μ)";i:2;s:18:"Panjang sampel (L)";}','Which parameters are needed to calculate permeability using Darcy''s Law?','a:4:{i:0;s:13:"Flow rate (Q)";i:1;s:20:"Fluid viscosity (μ)";i:2;s:17:"Sample length (L)";i:3;s:16:"Cementation type";}','a:3:{i:0;s:13:"Flow rate (Q)";i:1;s:20:"Fluid viscosity (μ)";i:2;s:17:"Sample length (L)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000390','Apa itu saturasi air irreducible (Swir)?','option','PFC000000002','Final Test','a:4:{i:0;s:68:"Saturasi air maksimum yang tidak dapat dipindahkan oleh gaya kapiler";i:1;s:56:"Saturasi air minimum yang dapat dicapai saat injeksi air";i:2;s:50:"Saturasi air saat reservoir pertama kali ditemukan";i:3;s:50:"Volume air yang terperangkap dalam kristal mineral";}','','Saturasi air maksimum yang tidak dapat dipindahkan oleh gaya kapiler','What is irreducible water saturation (Swir)?','a:4:{i:0;s:73:"The maximum water saturation that cannot be displaced by capillary forces";i:1;s:61:"The minimum water saturation reachable during water injection";i:2;s:60:"The water saturation when the reservoir was first discovered";i:3;s:51:"The volume of water trapped within mineral crystals";}','The maximum water saturation that cannot be displaced by capillary forces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000391','Apa kegunaan utama data tekanan kapiler (Pc) dalam petrofisika?','option','PFC000000002','Final Test','a:4:{i:0;s:82:"Menentukan distribusi saturasi fluida terhadap ketinggian di atas free water level";i:1;s:41:"Mengukur kecepatan rambat gelombang suara";i:2;s:36:"Menghitung nilai porositas rata-rata";i:3;s:28:"Menentukan viskositas minyak";}','','Menentukan distribusi saturasi fluida terhadap ketinggian di atas free water level','What is the primary use of capillary pressure (Pc) data in petrophysics?','a:4:{i:0;s:78:"Determining fluid saturation distribution versus height above free water level";i:1;s:29:"Measuring sonic wave velocity";i:2;s:34:"Calculating average porosity value";i:3;s:25:"Determining oil viscosity";}','Determining fluid saturation distribution versus height above free water level','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000392','Bagaimana hubungan antara ukuran butir dengan permeabilitas pada batuan sedimen?','option','PFC000000002','Final Test','a:4:{i:0;s:63:"Semakin besar butiran, cenderung semakin besar permeabilitasnya";i:1;s:63:"Semakin kecil butiran, cenderung semakin besar permeabilitasnya";i:2;s:53:"Ukuran butir tidak berpengaruh terhadap permeabilitas";i:3;s:33:"Hubungan keduanya linear terbalik";}','','Semakin besar butiran, cenderung semakin besar permeabilitasnya','How is grain size related to permeability in sedimentary rocks?','a:4:{i:0;s:46:"Larger grains tend to have higher permeability";i:1;s:47:"Smaller grains tend to have higher permeability";i:2;s:40:"Grain size has no effect on permeability";i:3;s:40:"They have an inverse linear relationship";}','Larger grains tend to have higher permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000393','Apa yang dimaksud dengan wettability dalam konteks saturasi fluida?','option','PFC000000002','Final Test','a:4:{i:0;s:53:"Preferensi batuan untuk dibasahi oleh fluida tertentu";i:1;s:34:"Kemampuan batuan untuk menahan air";i:2;s:39:"Kecepatan fluida mengalir di dalam pori";i:3;s:35:"Derajat kekasaran permukaan butiran";}','','Preferensi batuan untuk dibasahi oleh fluida tertentu','What is meant by wettability in the context of fluid saturation?','a:4:{i:0;s:55:"The preference of rock to be wetted by a specific fluid";i:1;s:35:"The ability of rock to retain water";i:2;s:36:"The speed of fluid flow within pores";i:3;s:37:"The degree of grain surface roughness";}','The preference of rock to be wetted by a specific fluid','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000394','Manakah metode laboratorium untuk menentukan saturasi fluida pada core sample?','option','PFC000000002','Final Test','a:4:{i:0;s:26:"Metode Retort Distillation";i:1;s:23:"Metode Helium Expansion";i:2;s:24:"Metode Mercury Injection";i:3;s:17:"Metode Darcy Flow";}','','Metode Retort Distillation','Which laboratory method is used to determine fluid saturation on a core sample?','a:4:{i:0;s:26:"Retort Distillation method";i:1;s:23:"Helium Expansion method";i:2;s:24:"Mercury Injection method";i:3;s:17:"Darcy Flow method";}','Retort Distillation method','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000395','Apa pengaruh gas terlarut terhadap kompresibilitas minyak?','option','PFC000000002','Final Test','a:4:{i:0;s:35:"Meningkatkan kompresibilitas minyak";i:1;s:33:"Menurunkan kompresibilitas minyak";i:2;s:18:"Tidak ada pengaruh";i:3;s:28:"Membuat minyak menjadi padat";}','','Meningkatkan kompresibilitas minyak','What is the effect of dissolved gas on oil compressibility?','a:4:{i:0;s:29:"Increases oil compressibility";i:1;s:29:"Decreases oil compressibility";i:2;s:9:"No effect";i:3;s:15:"Makes oil solid";}','Increases oil compressibility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000396','Satuan standar internasional untuk permeabilitas adalah?','option','PFC000000002','Final Test','a:4:{i:0;s:5:"Darcy";i:1;s:6:"Pascal";i:2;s:5:"Poise";i:3;s:6:"Micron";}','','Darcy','The standard international unit for permeability is?','a:4:{i:0;s:5:"Darcy";i:1;s:6:"Pascal";i:2;s:5:"Poise";i:3;s:6:"Micron";}','Darcy','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000397','Apa yang terjadi jika batuan memiliki sortasi yang buruk (poorly sorted)?','option','PFC000000002','Final Test','a:4:{i:0;s:86:"Porositas cenderung lebih rendah karena butiran kecil mengisi pori antar butiran besar";i:1;s:32:"Porositas cenderung lebih tinggi";i:2;s:35:"Permeabilitas menjadi sangat tinggi";i:3;s:32:"Batuan menjadi tidak kompresibel";}','','Porositas cenderung lebih rendah karena butiran kecil mengisi pori antar butiran besar','What happens if a rock is poorly sorted?','a:4:{i:0;s:82:"Porosity tends to be lower because smaller grains fill pores between larger grains";i:1;s:27:"Porosity tends to be higher";i:2;s:30:"Permeability becomes very high";i:3;s:31:"The rock becomes incompressible";}','Porosity tends to be lower because smaller grains fill pores between larger grains','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000398','Pilih elemen yang merupakan bagian dari perhitungan porositas total.','multi','PFC000000002','Final Test','a:4:{i:0;s:16:"Porositas primer";i:1;s:18:"Porositas sekunder";i:2;s:12:"Saturasi air";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:16:"Porositas primer";i:1;s:18:"Porositas sekunder";}','Select the elements that are part of the total porosity calculation.','a:4:{i:0;s:16:"Primary porosity";i:1;s:18:"Secondary porosity";i:2;s:16:"Water saturation";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:16:"Primary porosity";i:1;s:18:"Secondary porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000399','Mengapa pengukuran permeabilitas pada kondisi laboratorium harus dikoreksi ke kondisi reservoir?','option','PFC000000002','Final Test','a:4:{i:0;s:50:"Karena perbedaan tekanan overburden dan temperatur";i:1;s:37:"Karena alat laboratorium tidak akurat";i:2;s:41:"Karena fluida laboratorium selalu berbeda";i:3;s:51:"Karena permeabilitas tidak berubah dengan kedalaman";}','','Karena perbedaan tekanan overburden dan temperatur','Why must permeability measurements at laboratory conditions be corrected to reservoir conditions?','a:4:{i:0;s:61:"Because of differences in overburden pressure and temperature";i:1;s:42:"Because laboratory equipment is inaccurate";i:2;s:46:"Because laboratory fluids are always different";i:3;s:47:"Because permeability does not change with depth";}','Because of differences in overburden pressure and temperature','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000400','Parameter utama yang menggambarkan rasio volume minyak pada kondisi reservoir terhadap volume minyak pada kondisi standar (tangki) adalah','option','PFC000000003','Final Test','a:4:{i:0;s:33:"Faktor volume formasi minyak (Bo)";i:1;s:17:"Viskositas minyak";i:2;s:25:"Kompresibilitas isotermal";i:3;s:16:"Densitas relatif";}','','Faktor volume formasi minyak (Bo)','The main parameter describing the ratio of oil volume at reservoir conditions to oil volume at standard (tank) conditions is','a:4:{i:0;s:32:"Oil formation volume factor (Bo)";i:1;s:13:"Oil viscosity";i:2;s:26:"Isothermal compressibility";i:3;s:16:"Relative density";}','Oil formation volume factor (Bo)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000401','Faktor apa saja yang menyebabkan penurunan viskositas minyak mentah dalam reservoir?','multi','PFC000000003','Final Test','a:4:{i:0;s:22:"Peningkatan temperatur";i:1;s:19:"Peningkatan tekanan";i:2;s:38:"Kelarutan gas yang tinggi dalam minyak";i:3;s:21:"Kehadiran air formasi";}','','a:2:{i:0;s:22:"Peningkatan temperatur";i:1;s:38:"Kelarutan gas yang tinggi dalam minyak";}','Which factors cause a decrease in crude oil viscosity within the reservoir?','a:4:{i:0;s:20:"Temperature increase";i:1;s:17:"Pressure increase";i:2;s:26:"High gas solubility in oil";i:3;s:27:"Presence of formation water";}','a:2:{i:0;s:20:"Temperature increase";i:1;s:26:"High gas solubility in oil";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000402','Pada tekanan di atas tekanan titik gelembung (bubble point), perubahan faktor volume formasi minyak (Bo) terhadap tekanan adalah','option','PFC000000003','Final Test','a:4:{i:0;s:40:"Menurun seiring dengan penurunan tekanan";i:1;s:42:"Meningkat seiring dengan penurunan tekanan";i:2;s:13:"Tetap konstan";i:3;s:24:"Berfluktuasi secara acak";}','','Meningkat seiring dengan penurunan tekanan','At pressures above the bubble point, the change in oil formation volume factor (Bo) with respect to pressure is','a:4:{i:0;s:32:"Decreasing as pressure decreases";i:1;s:32:"Increasing as pressure decreases";i:2;s:8:"Constant";i:3;s:20:"Fluctuating randomly";}','Increasing as pressure decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000403','Kompresibilitas isotermal minyak (Co) didefinisikan sebagai perubahan volume per satuan volume akibat perubahan','option','PFC000000003','Final Test','a:4:{i:0;s:7:"Tekanan";i:1;s:10:"Temperatur";i:2;s:10:"Viskositas";i:3;s:8:"Densitas";}','','Tekanan','Oil isothermal compressibility (Co) is defined as the change in volume per unit volume due to a change in','a:4:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:9:"Viscosity";i:3;s:7:"Density";}','Pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000404','Manakah pernyataan yang benar mengenai densitas air formasi seiring dengan kedalaman reservoir?','option','PFC000000003','Final Test','a:4:{i:0;s:50:"Meningkat karena peningkatan salinitas dan tekanan";i:1;s:37:"Menurun karena peningkatan temperatur";i:2;s:43:"Tetap konstan karena air tidak termampatkan";i:3;s:37:"Meningkat hanya jika ada gas terlarut";}','','Meningkat karena peningkatan salinitas dan tekanan','Which statement is correct regarding formation water density with increasing reservoir depth?','a:4:{i:0;s:48:"Increases due to increased salinity and pressure";i:1;s:38:"Decreases due to increased temperature";i:2;s:48:"Remains constant because water is incompressible";i:3;s:42:"Increases only if dissolved gas is present";}','Increases due to increased salinity and pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000405','Gas yang berada pada kondisi tekanan dan temperatur di atas titik kritisnya disebut sebagai','option','PFC000000003','Final Test','a:4:{i:0;s:18:"Fluida superkritis";i:1;s:9:"Gas basah";i:2;s:10:"Gas kering";i:3;s:9:"Kondensat";}','','Fluida superkritis','Gas at pressure and temperature conditions above its critical point is called','a:4:{i:0;s:19:"Supercritical fluid";i:1;s:7:"Wet gas";i:2;s:7:"Dry gas";i:3;s:10:"Condensate";}','Supercritical fluid','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000406','Faktor volume formasi gas (Bg) pada kondisi standar dinyatakan dengan satuan','option','PFC000000003','Final Test','a:4:{i:0;s:7:"bbl/SCF";i:1;s:7:"SCF/STB";i:2;s:2:"cP";i:3;s:4:"psia";}','','bbl/SCF','The gas formation volume factor (Bg) at standard conditions is expressed in units of','a:4:{i:0;s:7:"bbl/SCF";i:1;s:7:"SCF/STB";i:2;s:2:"cP";i:3;s:4:"psia";}','bbl/SCF','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000407','Apa yang terjadi pada rasio gas-minyak terlarut (Rs) ketika tekanan turun di bawah tekanan titik gelembung?','option','PFC000000003','Final Test','a:4:{i:0;s:10:"Rs menurun";i:1;s:12:"Rs meningkat";i:2;s:16:"Rs tidak berubah";i:3;s:28:"Rs menjadi nol secara instan";}','','Rs menurun','What happens to the solution gas-oil ratio (Rs) when the pressure drops below the bubble point pressure?','a:4:{i:0;s:12:"Rs decreases";i:1;s:12:"Rs increases";i:2;s:20:"Rs remains unchanged";i:3;s:25:"Rs becomes zero instantly";}','Rs decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000408','Sifat fisik fluida yang sangat dipengaruhi oleh jumlah gas yang terlarut di dalam minyak adalah','multi','PFC000000003','Final Test','a:4:{i:0;s:17:"Viskositas minyak";i:1;s:26:"Faktor volume formasi (Bo)";i:2;s:15:"Densitas minyak";i:3;s:13:"Salinitas air";}','','a:3:{i:0;s:17:"Viskositas minyak";i:1;s:26:"Faktor volume formasi (Bo)";i:2;s:15:"Densitas minyak";}','Physical properties of fluids that are significantly influenced by the amount of gas dissolved in oil are','a:4:{i:0;s:13:"Oil viscosity";i:1;s:28:"Formation volume factor (Bo)";i:2;s:11:"Oil density";i:3;s:14:"Water salinity";}','a:3:{i:0;s:13:"Oil viscosity";i:1;s:28:"Formation volume factor (Bo)";i:2;s:11:"Oil density";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000409','Tekanan di mana gelembung gas pertama kali muncul dari fase cair minyak disebut','option','PFC000000003','Final Test','a:4:{i:0;s:47:"Tekanan titik gelembung (bubble point pressure)";i:1;s:40:"Tekanan titik embun (dew point pressure)";i:2;s:16:"Tekanan kritikal";i:3;s:19:"Tekanan hidrostatis";}','','Tekanan titik gelembung (bubble point pressure)','The pressure at which the first gas bubble emerges from the oil liquid phase is called','a:4:{i:0;s:21:"Bubble point pressure";i:1;s:18:"Dew point pressure";i:2;s:17:"Critical pressure";i:3;s:20:"Hydrostatic pressure";}','Bubble point pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000410','Faktor volume formasi air (Bw) umumnya bernilai','option','PFC000000003','Final Test','a:4:{i:0;s:11:"Mendekati 1";i:1;s:25:"Sangat besar (di atas 10)";i:2;s:27:"Sangat kecil (di bawah 0,1)";i:3;s:7:"Negatif";}','','Mendekati 1','The water formation volume factor (Bw) is generally','a:4:{i:0;s:10:"Close to 1";i:1;s:21:"Very large (above 10)";i:2;s:22:"Very small (below 0.1)";i:3;s:8:"Negative";}','Close to 1','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000411','Apa dampak dari peningkatan salinitas terhadap viskositas air formasi?','option','PFC000000003','Final Test','a:4:{i:0;s:23:"Meningkatkan viskositas";i:1;s:21:"Menurunkan viskositas";i:2;s:17:"Tidak berpengaruh";i:3;s:33:"Membuat air menjadi non-newtonian";}','','Meningkatkan viskositas','What is the impact of increased salinity on formation water viscosity?','a:4:{i:0;s:19:"Increases viscosity";i:1;s:19:"Decreases viscosity";i:2;s:9:"No effect";i:3;s:25:"Makes water non-newtonian";}','Increases viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000412','Dalam diagram fase P-T, daerah di mana fluida berada dalam dua fase (cair dan gas) dibatasi oleh','option','PFC000000003','Final Test','a:4:{i:0;s:37:"Kurva titik gelembung dan titik embun";i:1;s:15:"Garis isotermal";i:2;s:12:"Garis isokor";i:3;s:12:"Titik kritis";}','','Kurva titik gelembung dan titik embun','In a P-T phase diagram, the region where fluid exists in two phases (liquid and gas) is bounded by','a:4:{i:0;s:33:"Bubble point and dew point curves";i:1;s:16:"Isothermal lines";i:2;s:14:"Isochore lines";i:3;s:14:"Critical point";}','Bubble point and dew point curves','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000413','Manakah dari berikut ini yang merupakan sifat fluida yang ditentukan melalui eksperimen laboratorium PVT?','multi','PFC000000003','Final Test','a:4:{i:0;s:23:"Tekanan titik gelembung";i:1;s:21:"Rasio gas-minyak (Rs)";i:2;s:21:"Permeabilitas absolut";i:3;s:26:"Faktor volume formasi (Bo)";}','','a:3:{i:0;s:23:"Tekanan titik gelembung";i:1;s:21:"Rasio gas-minyak (Rs)";i:2;s:26:"Faktor volume formasi (Bo)";}','Which of the following are fluid properties determined through PVT laboratory experiments?','a:4:{i:0;s:21:"Bubble point pressure";i:1;s:18:"Gas-oil ratio (Rs)";i:2;s:21:"Absolute permeability";i:3;s:28:"Formation volume factor (Bo)";}','a:3:{i:0;s:21:"Bubble point pressure";i:1;s:18:"Gas-oil ratio (Rs)";i:2;s:28:"Formation volume factor (Bo)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000414','Nilai kompresibilitas air (Cw) biasanya lebih kecil daripada kompresibilitas minyak karena','option','PFC000000003','Final Test','a:4:{i:0;s:43:"Air lebih sulit dimampatkan daripada minyak";i:1;s:34:"Air memiliki densitas lebih rendah";i:2;s:33:"Air tidak mengandung gas terlarut";i:3;s:27:"Viskositas air lebih rendah";}','','Air lebih sulit dimampatkan daripada minyak','The value of water compressibility (Cw) is usually smaller than oil compressibility because','a:4:{i:0;s:36:"Water is harder to compress than oil";i:1;s:23:"Water has lower density";i:2;s:36:"Water does not contain dissolved gas";i:3;s:24:"Water viscosity is lower";}','Water is harder to compress than oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000415','Gas yang mengandung sedikit atau tidak ada hidrokarbon cair pada kondisi permukaan disebut','option','PFC000000003','Final Test','a:4:{i:0;s:10:"Gas kering";i:1;s:9:"Gas basah";i:2;s:9:"Kondensat";i:3;s:15:"Minyak volatile";}','','Gas kering','Gas that contains little or no liquid hydrocarbons at surface conditions is called','a:4:{i:0;s:7:"Dry gas";i:1;s:7:"Wet gas";i:2;s:10:"Condensate";i:3;s:12:"Volatile oil";}','Dry gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000416','Pengaruh kenaikan temperatur pada viskositas gas adalah','option','PFC000000003','Final Test','a:4:{i:0;s:23:"Meningkatkan viskositas";i:1;s:21:"Menurunkan viskositas";i:2;s:13:"Tetap konstan";i:3;s:23:"Bergantung pada tekanan";}','','Meningkatkan viskositas','The effect of temperature increase on gas viscosity is','a:4:{i:0;s:19:"Increases viscosity";i:1;s:19:"Decreases viscosity";i:2;s:8:"Constant";i:3;s:21:"Dependent on pressure";}','Increases viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000417','Parameter utama yang menentukan klasifikasi fluida reservoir dalam diagram fase adalah','option','PFC000000003','Final Test','a:4:{i:0;s:17:"Komposisi kimiawi";i:1;s:12:"Warna fluida";i:2;s:19:"Kedalaman reservoir";i:3;s:21:"Kecepatan alir fluida";}','','Komposisi kimiawi','The main parameter that determines the classification of reservoir fluids in a phase diagram is','a:4:{i:0;s:20:"Chemical composition";i:1;s:11:"Fluid color";i:2;s:15:"Reservoir depth";i:3;s:19:"Fluid flow velocity";}','Chemical composition','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000418','Jika tekanan reservoir turun di bawah tekanan titik embun pada reservoir gas kondensat, maka akan terjadi','option','PFC000000003','Final Test','a:4:{i:0;s:23:"Retrograde condensation";i:1;s:16:"Evaporasi cairan";i:2;s:21:"Pembentukan gas murni";i:3;s:29:"Peningkatan viskositas minyak";}','','Retrograde condensation','If the reservoir pressure drops below the dew point pressure in a gas condensate reservoir, it will result in','a:4:{i:0;s:23:"Retrograde condensation";i:1;s:18:"Liquid evaporation";i:2;s:21:"Formation of pure gas";i:3;s:25:"Increase in oil viscosity";}','Retrograde condensation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000419','Faktor volume formasi air (Bw) dipengaruhi oleh','multi','PFC000000003','Final Test','a:4:{i:0;s:7:"Tekanan";i:1;s:10:"Temperatur";i:2;s:9:"Salinitas";i:3;s:13:"Permeabilitas";}','','a:3:{i:0;s:7:"Tekanan";i:1;s:10:"Temperatur";i:2;s:9:"Salinitas";}','The water formation volume factor (Bw) is influenced by','a:4:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:8:"Salinity";i:3;s:12:"Permeability";}','a:3:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:8:"Salinity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000420','Log gamma ray digunakan terutama untuk menentukan karakteristik apa dari formasi?','option','PFC000000004','Final Test','a:4:{i:0;s:29:"Litologi dan kandungan serpih";i:1;s:16:"Porositas batuan";i:2;s:12:"Saturasi air";i:3;s:21:"Permeabilitas absolut";}','','Litologi dan kandungan serpih','The gamma ray log is primarily used to determine which formation characteristic?','a:4:{i:0;s:27:"Lithology and shale content";i:1;s:13:"Rock porosity";i:2;s:16:"Water saturation";i:3;s:21:"Absolute permeability";}','Lithology and shale content','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000421','Faktor apa yang dapat memengaruhi pembacaan log resistivitas dalam lingkungan lubang bor?','multi','PFC000000004','Final Test','a:4:{i:0;s:25:"Infiltrasi filtrat lumpur";i:1;s:19:"Diameter lubang bor";i:2;s:18:"Ketebalan mud cake";i:3;s:20:"Kecepatan pengeboran";}','','a:3:{i:0;s:25:"Infiltrasi filtrat lumpur";i:1;s:19:"Diameter lubang bor";i:2;s:18:"Ketebalan mud cake";}','What factors can affect resistivity log readings in the borehole environment?','a:4:{i:0;s:21:"Mud filtrate invasion";i:1;s:17:"Borehole diameter";i:2;s:18:"Mud cake thickness";i:3;s:13:"Drilling rate";}','a:3:{i:0;s:21:"Mud filtrate invasion";i:1;s:17:"Borehole diameter";i:2;s:18:"Mud cake thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000422','Log neutron mengukur konsentrasi apa di dalam formasi untuk menentukan porositas?','option','PFC000000004','Final Test','a:4:{i:0;s:11:"Ion klorida";i:1;s:8:"Hidrogen";i:2;s:6:"Karbon";i:3;s:6:"Sulfur";}','','Hidrogen','The neutron log measures the concentration of what within the formation to determine porosity?','a:4:{i:0;s:13:"Chloride ions";i:1;s:8:"Hydrogen";i:2;s:6:"Carbon";i:3;s:6:"Sulfur";}','Hydrogen','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000423','Prinsip kerja log densitas didasarkan pada interaksi apa antara radiasi gamma dengan elektron batuan?','option','PFC000000004','Final Test','a:4:{i:0;s:16:"Efek fotolistrik";i:1;s:16:"Hamburan Compton";i:2;s:17:"Produksi pasangan";i:3;s:15:"Radiasi sinar-X";}','','Hamburan Compton','The density log working principle is based on what interaction between gamma radiation and rock electrons?','a:4:{i:0;s:20:"Photoelectric effect";i:1;s:18:"Compton scattering";i:2;s:15:"Pair production";i:3;s:15:"X-ray radiation";}','Compton scattering','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000424','Apa fungsi utama dari log caliper dalam operasi wireline logging?','option','PFC000000004','Final Test','a:4:{i:0;s:28:"Mengukur diameter lubang bor";i:1;s:24:"Mengukur tekanan formasi";i:2;s:24:"Mengukur suhu lubang bor";i:3;s:28:"Mengukur resistivitas lumpur";}','','Mengukur diameter lubang bor','What is the primary function of the caliper log in wireline logging operations?','a:4:{i:0;s:27:"Measuring borehole diameter";i:1;s:28:"Measuring formation pressure";i:2;s:30:"Measuring borehole temperature";i:3;s:25:"Measuring mud resistivity";}','Measuring borehole diameter','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000425','Log sonic (akustik) mengukur waktu tempuh gelombang suara untuk menentukan apa?','option','PFC000000004','Final Test','a:4:{i:0;s:18:"Porositas sekunder";i:1;s:41:"Porositas transit (interval transit time)";i:2;s:20:"Saturasi hidrokarbon";i:3;s:16:"Kekerasan batuan";}','','Porositas transit (interval transit time)','The sonic log measures sound wave travel time to determine what?','a:4:{i:0;s:18:"Secondary porosity";i:1;s:30:"Interval transit time porosity";i:2;s:22:"Hydrocarbon saturation";i:3;s:13:"Rock hardness";}','Interval transit time porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000426','Mengapa koreksi borehole diperlukan pada data log?','multi','PFC000000004','Final Test','a:4:{i:0;s:56:"Karena pengaruh diameter lubang bor yang tidak beraturan";i:1;s:27:"Karena adanya efek mud cake";i:2;s:36:"Untuk meningkatkan kecepatan logging";i:3;s:38:"Karena efek lingkungan lumpur (invasi)";}','','a:3:{i:0;s:56:"Karena pengaruh diameter lubang bor yang tidak beraturan";i:1;s:27:"Karena adanya efek mud cake";i:2;s:38:"Karena efek lingkungan lumpur (invasi)";}','Why is borehole correction required for log data?','a:4:{i:0;s:42:"Due to irregular borehole diameter effects";i:1;s:23:"Due to mud cake effects";i:2;s:25:"To increase logging speed";i:3;s:41:"Due to mud environment (invasion) effects";}','a:3:{i:0;s:42:"Due to irregular borehole diameter effects";i:1;s:23:"Due to mud cake effects";i:2;s:41:"Due to mud environment (invasion) effects";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000427','Apa yang dimaksud dengan ''invasi'' dalam konteks lingkungan lubang bor?','option','PFC000000004','Final Test','a:4:{i:0;s:40:"Masuknya filtrat lumpur ke dalam formasi";i:1;s:38:"Keluarnya fluida formasi ke lubang bor";i:2;s:28:"Runtuhnya dinding lubang bor";i:3;s:24:"Penyumbatan alat logging";}','','Masuknya filtrat lumpur ke dalam formasi','What is meant by ''invasion'' in the context of the borehole environment?','a:4:{i:0;s:47:"Infiltration of mud filtrate into the formation";i:1;s:44:"Outflow of formation fluid into the borehole";i:2;s:29:"Collapse of the borehole wall";i:3;s:28:"Clogging of the logging tool";}','Infiltration of mud filtrate into the formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000428','Log SP (Spontaneous Potential) paling efektif digunakan jika lumpur pengeboran bersifat apa?','option','PFC000000004','Final Test','a:4:{i:0;s:32:"Berbasis air tawar (water-based)";i:1;s:27:"Berbasis minyak (oil-based)";i:2;s:19:"Udara (air-drilled)";i:3;s:10:"Semen cair";}','','Berbasis air tawar (water-based)','The SP log is most effective when the drilling mud is of what type?','a:4:{i:0;s:11:"Water-based";i:1;s:9:"Oil-based";i:2;s:11:"Air-drilled";i:3;s:13:"Liquid cement";}','Water-based','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000429','Apa yang diukur oleh log Photoelectric Factor (PEF) yang sering menyertai log densitas?','option','PFC000000004','Final Test','a:4:{i:0;s:29:"Nomor atom efektif (litologi)";i:1;s:13:"Densitas bulk";i:2;s:15:"Porositas total";i:3;s:12:"Saturasi air";}','','Nomor atom efektif (litologi)','What does the Photoelectric Factor (PEF) log, which often accompanies the density log, measure?','a:4:{i:0;s:35:"Effective atomic number (lithology)";i:1;s:12:"Bulk density";i:2;s:14:"Total porosity";i:3;s:16:"Water saturation";}','Effective atomic number (lithology)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000430','Dalam kondisi apa log sonic sering memberikan pembacaan porositas yang terlalu tinggi?','option','PFC000000004','Final Test','a:4:{i:0;s:42:"Adanya porositas sekunder (vuggy/fracture)";i:1;s:26:"Formasi yang sangat kompak";i:2;s:24:"Adanya gas dalam formasi";i:3;s:26:"Batuan sedimen yang bersih";}','','Adanya porositas sekunder (vuggy/fracture)','Under what conditions does the sonic log often provide overly high porosity readings?','a:4:{i:0;s:47:"Presence of secondary porosity (vugs/fractures)";i:1;s:24:"Highly compact formation";i:2;s:32:"Presence of gas in the formation";i:3;s:22:"Clean sedimentary rock";}','Presence of secondary porosity (vugs/fractures)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000431','Apa perbedaan utama antara densitas bulk dan densitas matriks?','option','PFC000000004','Final Test','a:4:{i:0;s:83:"Densitas bulk mencakup pori berisi fluida, densitas matriks adalah densitas mineral";i:1;s:75:"Densitas bulk adalah densitas batuan kering, densitas matriks mencakup pori";i:2;s:37:"Densitas bulk hanya untuk batuan beku";i:3;s:19:"Tidak ada perbedaan";}','','Densitas bulk mencakup pori berisi fluida, densitas matriks adalah densitas mineral','What is the main difference between bulk density and matrix density?','a:4:{i:0;s:75:"Bulk density includes fluid-filled pores, matrix density is mineral density";i:1;s:63:"Bulk density is dry rock density, matrix density includes pores";i:2;s:38:"Bulk density is only for igneous rocks";i:3;s:22:"There is no difference";}','Bulk density includes fluid-filled pores, matrix density is mineral density','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000432','Log resistivitas dalam (Deep Resistivity) digunakan untuk apa?','option','PFC000000004','Final Test','a:4:{i:0;s:55:"Mengukur resistivitas zona formasi yang belum terinvasi";i:1;s:30:"Mengukur resistivitas mud cake";i:2;s:24:"Mengukur diameter lubang";i:3;s:36:"Mengukur resistivitas filtrat lumpur";}','','Mengukur resistivitas zona formasi yang belum terinvasi','What is the deep resistivity log used for?','a:4:{i:0;s:53:"Measuring resistivity of the uninvaded formation zone";i:1;s:30:"Measuring mud cake resistivity";i:2;s:23:"Measuring hole diameter";i:3;s:34:"Measuring mud filtrate resistivity";}','Measuring resistivity of the uninvaded formation zone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000433','Apa dampak keberadaan gas terhadap log densitas dan log neutron?','option','PFC000000004','Final Test','a:4:{i:0;s:47:"Densitas terbaca rendah, neutron terbaca rendah";i:1;s:47:"Densitas terbaca tinggi, neutron terbaca tinggi";i:2;s:47:"Densitas terbaca rendah, neutron terbaca tinggi";i:3;s:47:"Densitas terbaca tinggi, neutron terbaca rendah";}','','Densitas terbaca rendah, neutron terbaca rendah','What is the effect of gas presence on the density and neutron logs?','a:4:{i:0;s:36:"Density reads low, neutron reads low";i:1;s:38:"Density reads high, neutron reads high";i:2;s:37:"Density reads low, neutron reads high";i:3;s:37:"Density reads high, neutron reads low";}','Density reads low, neutron reads low','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000434','Log resistivitas dangkal (Shallow Resistivity) paling sensitif terhadap apa?','option','PFC000000004','Final Test','a:4:{i:0;s:34:"Zona terinvasi oleh filtrat lumpur";i:1;s:38:"Zona formasi yang jauh dari lubang bor";i:2;s:36:"Zona formasi yang jenuh minyak murni";i:3;s:27:"Zona formasi yang jenuh gas";}','','Zona terinvasi oleh filtrat lumpur','What is the shallow resistivity log most sensitive to?','a:4:{i:0;s:28:"Zone invaded by mud filtrate";i:1;s:36:"Formation zone far from the borehole";i:2;s:38:"Formation zone saturated with pure oil";i:3;s:33:"Formation zone saturated with gas";}','Zone invaded by mud filtrate','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000435','Apa kegunaan utama dari log SP di lapangan?','multi','PFC000000004','Final Test','a:4:{i:0;s:30:"Identifikasi lapisan permeabel";i:1;s:39:"Penentuan resistivitas air formasi (Rw)";i:2;s:23:"Penentuan kandungan gas";i:3;s:20:"Korelasi antar sumur";}','','a:3:{i:0;s:30:"Identifikasi lapisan permeabel";i:1;s:39:"Penentuan resistivitas air formasi (Rw)";i:2;s:20:"Korelasi antar sumur";}','What are the primary uses of the SP log in the field?','a:4:{i:0;s:32:"Identification of permeable beds";i:1;s:49:"Determination of formation water resistivity (Rw)";i:2;s:28:"Determination of gas content";i:3;s:24:"Well-to-well correlation";}','a:3:{i:0;s:32:"Identification of permeable beds";i:1;s:49:"Determination of formation water resistivity (Rw)";i:2;s:24:"Well-to-well correlation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000436','Manakah pernyataan yang benar mengenai pengaruh mud cake pada log?','option','PFC000000004','Final Test','a:4:{i:0;s:65:"Dapat menyebabkan pembacaan log resistivitas menjadi tidak akurat";i:1;s:42:"Tidak memengaruhi alat logging sama sekali";i:2;s:31:"Hanya memengaruhi log gamma ray";i:3;s:29:"Hanya memengaruhi log neutron";}','','Dapat menyebabkan pembacaan log resistivitas menjadi tidak akurat','Which statement is correct regarding the effect of mud cake on logs?','a:4:{i:0;s:51:"Can cause resistivity log readings to be inaccurate";i:1;s:36:"Does not affect logging tools at all";i:2;s:27:"Only affects gamma ray logs";i:3;s:25:"Only affects neutron logs";}','Can cause resistivity log readings to be inaccurate','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000437','Dalam kondisi lubang bor yang tidak stabil (washout), apa yang terjadi pada pembacaan log densitas?','option','PFC000000004','Final Test','a:4:{i:0;s:60:"Pembacaan densitas menjadi lebih rendah dari yang sebenarnya";i:1;s:60:"Pembacaan densitas menjadi lebih tinggi dari yang sebenarnya";i:2;s:42:"Tidak ada pengaruh pada pembacaan densitas";i:3;s:30:"Pembacaan densitas menjadi nol";}','','Pembacaan densitas menjadi lebih rendah dari yang sebenarnya','In unstable borehole conditions (washout), what happens to the density log reading?','a:4:{i:0;s:51:"Density reading becomes lower than the actual value";i:1;s:52:"Density reading becomes higher than the actual value";i:2;s:28:"No effect on density reading";i:3;s:28:"Density reading becomes zero";}','Density reading becomes lower than the actual value','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000438','Log apa yang paling baik untuk mendeteksi mineral evaporit seperti halit?','option','PFC000000004','Final Test','a:4:{i:0;s:20:"Log densitas-neutron";i:1;s:13:"Log gamma ray";i:2;s:16:"Log resistivitas";i:3;s:6:"Log SP";}','','Log densitas-neutron','Which log is best for detecting evaporite minerals like halite?','a:4:{i:0;s:19:"Density-neutron log";i:1;s:13:"Gamma ray log";i:2;s:15:"Resistivity log";i:3;s:6:"SP log";}','Density-neutron log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000439','Apa tujuan dari melakukan ''environmental correction'' pada data log wireline?','option','PFC000000004','Final Test','a:4:{i:0;s:58:"Menghilangkan pengaruh kondisi lubang bor dari data mentah";i:1;s:35:"Meningkatkan resolusi vertikal alat";i:2;s:29:"Mengubah jenis fluida formasi";i:3;s:33:"Menambah kedalaman penetrasi alat";}','','Menghilangkan pengaruh kondisi lubang bor dari data mentah','What is the purpose of performing ''environmental correction'' on wireline log data?','a:4:{i:0;s:57:"To remove the effect of borehole conditions from raw data";i:1;s:47:"To increase the vertical resolution of the tool";i:2;s:34:"To change the formation fluid type";i:3;s:43:"To increase the tool''s depth of penetration";}','To remove the effect of borehole conditions from raw data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000440','Parameter utama yang diperlukan dalam persamaan Archie untuk menghitung saturasi air (Sw) pada reservoir clean sand adalah','option','PFC000000005','Final Test','a:4:{i:0;s:58:"Porositas, eksponen saturasi (n), dan faktor sementasi (m)";i:1;s:33:"Salinitas lumpur dan suhu formasi";i:2;s:33:"Densitas batuan dan permeabilitas";i:3;s:39:"Tekanan reservoir dan viskositas minyak";}','','Porositas, eksponen saturasi (n), dan faktor sementasi (m)','The main parameters required in the Archie equation to calculate water saturation (Sw) in a clean sand reservoir are','a:4:{i:0;s:61:"Porosity, saturation exponent (n), and cementation factor (m)";i:1;s:38:"Mud salinity and formation temperature";i:2;s:29:"Rock density and permeability";i:3;s:36:"Reservoir pressure and oil viscosity";}','Porosity, saturation exponent (n), and cementation factor (m)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000441','Metode apa yang paling umum digunakan untuk menghitung volume shale (Vsh) dari log Gamma Ray?','option','PFC000000005','Final Test','a:4:{i:0;s:22:"Indeks Gamma Ray (Igr)";i:1;s:25:"Analisis log resistivitas";i:2;s:34:"Metode cross-plot densitas-neutron";i:3;s:24:"Analisis porositas sonic";}','','Indeks Gamma Ray (Igr)','What is the most common method used to calculate shale volume (Vsh) from the Gamma Ray log?','a:4:{i:0;s:21:"Gamma Ray Index (Igr)";i:1;s:24:"Resistivity log analysis";i:2;s:33:"Density-neutron cross-plot method";i:3;s:23:"Sonic porosity analysis";}','Gamma Ray Index (Igr)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000442','Faktor apa saja yang menyebabkan nilai porositas dari log densitas (PHID) menjadi lebih besar dari porositas sebenarnya?','multi','PFC000000005','Final Test','a:4:{i:0;s:37:"Adanya gas pada zona dekat lubang bor";i:1;s:29:"Kehadiran shale dalam matriks";i:2;s:27:"Kompaksi batuan yang tinggi";i:3;s:34:"Penebalan mud cake yang berlebihan";}','','a:2:{i:0;s:37:"Adanya gas pada zona dekat lubang bor";i:1;s:29:"Kehadiran shale dalam matriks";}','What factors cause the density log porosity (PHID) value to be larger than the actual porosity?','a:4:{i:0;s:41:"Presence of gas in the near-wellbore zone";i:1;s:31:"Presence of shale in the matrix";i:2;s:20:"High rock compaction";i:3;s:28:"Excessive mud cake thickness";}','a:2:{i:0;s:41:"Presence of gas in the near-wellbore zone";i:1;s:31:"Presence of shale in the matrix";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000443','Apa fungsi utama dari penentuan cut-off dalam evaluasi formasi?','option','PFC000000005','Final Test','a:4:{i:0;s:53:"Membedakan zona reservoir produktif dan non-produktif";i:1;s:26:"Menghitung tekanan kapiler";i:2;s:28:"Menentukan viskositas fluida";i:3;s:27:"Mengkalibrasi kedalaman log";}','','Membedakan zona reservoir produktif dan non-produktif','What is the main function of determining cut-offs in formation evaluation?','a:4:{i:0;s:61:"Differentiating productive and non-productive reservoir zones";i:1;s:30:"Calculating capillary pressure";i:2;s:27:"Determining fluid viscosity";i:3;s:21:"Calibrating log depth";}','Differentiating productive and non-productive reservoir zones','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000444','Dalam evaluasi net pay, kriteria cut-off yang umum digunakan meliputi','multi','PFC000000005','Final Test','a:4:{i:0;s:18:"Volume shale (Vsh)";i:1;s:15:"Porositas (phi)";i:2;s:17:"Saturasi air (Sw)";i:3;s:21:"Permeabilitas absolut";}','','a:3:{i:0;s:18:"Volume shale (Vsh)";i:1;s:15:"Porositas (phi)";i:2;s:17:"Saturasi air (Sw)";}','In net pay evaluation, common cut-off criteria include','a:4:{i:0;s:18:"Shale volume (Vsh)";i:1;s:14:"Porosity (phi)";i:2;s:21:"Water saturation (Sw)";i:3;s:21:"Absolute permeability";}','a:3:{i:0;s:18:"Shale volume (Vsh)";i:1;s:14:"Porosity (phi)";i:2;s:21:"Water saturation (Sw)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000445','Apa arti dari terminologi ''Net-to-Gross'' dalam zonasi reservoir?','option','PFC000000005','Final Test','a:4:{i:0;s:68:"Rasio ketebalan reservoir produktif terhadap total ketebalan formasi";i:1;s:39:"Rasio volume air terhadap volume minyak";i:2;s:48:"Rasio porositas efektif terhadap porositas total";i:3;s:26:"Rasio shale terhadap pasir";}','','Rasio ketebalan reservoir produktif terhadap total ketebalan formasi','What does the term ''Net-to-Gross'' mean in reservoir zonation?','a:4:{i:0;s:68:"Ratio of productive reservoir thickness to total formation thickness";i:1;s:35:"Ratio of water volume to oil volume";i:2;s:45:"Ratio of effective porosity to total porosity";i:3;s:22:"Ratio of shale to sand";}','Ratio of productive reservoir thickness to total formation thickness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000446','Persamaan Archie (Sw^n = (a * Rw) / (phi^m * Rt)) mengasumsikan bahwa batuan bersifat','option','PFC000000005','Final Test','a:4:{i:0;s:22:"Clean sand (non-shaly)";i:1;s:10:"Shaly sand";i:2;s:31:"Karbonat dengan porositas vuggy";i:3;s:14:"Batuan igneous";}','','Clean sand (non-shaly)','The Archie equation (Sw^n = (a * Rw) / (phi^m * Rt)) assumes that the rock is','a:4:{i:0;s:22:"Clean sand (non-shaly)";i:1;s:10:"Shaly sand";i:2;s:29:"Carbonate with vuggy porosity";i:3;s:12:"Igneous rock";}','Clean sand (non-shaly)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000447','Porositas efektif didefinisikan sebagai','option','PFC000000005','Final Test','a:4:{i:0;s:74:"Porositas yang saling berhubungan dan berkontribusi terhadap aliran fluida";i:1;s:29:"Total ruang pori dalam batuan";i:2;s:35:"Porositas yang terisi oleh air saja";i:3;s:41:"Porositas yang diukur oleh log sonic saja";}','','Porositas yang saling berhubungan dan berkontribusi terhadap aliran fluida','Effective porosity is defined as','a:4:{i:0;s:61:"Porosity that is interconnected and contributes to fluid flow";i:1;s:28:"Total pore space in the rock";i:2;s:29:"Porosity filled only by water";i:3;s:35:"Porosity measured only by sonic log";}','Porosity that is interconnected and contributes to fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000448','Log apa yang paling efektif untuk mendeteksi keberadaan shale (lempung) dalam formasi?','option','PFC000000005','Final Test','a:4:{i:0;s:13:"Log Gamma Ray";i:1;s:12:"Log Densitas";i:2;s:16:"Log Resistivitas";i:3;s:18:"Log Self-Potential";}','','Log Gamma Ray','Which log is most effective for detecting the presence of shale in a formation?','a:4:{i:0;s:13:"Gamma Ray log";i:1;s:11:"Density log";i:2;s:15:"Resistivity log";i:3;s:18:"Self-Potential log";}','Gamma Ray log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000449','Nilai faktor sementasi (m) dalam persamaan Archie pada batuan pasir terkonsolidasi biasanya bernilai','option','PFC000000005','Final Test','a:4:{i:0;s:1:"2";i:1;s:1:"1";i:2;s:1:"3";i:3;s:3:"0.5";}','','2','The cementation factor (m) value in the Archie equation for consolidated sandstones is typically','a:4:{i:0;s:1:"2";i:1;s:1:"1";i:2;s:1:"3";i:3;s:3:"0.5";}','2','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000450','Apa dampak kehadiran shale terhadap resistivitas batuan?','option','PFC000000005','Final Test','a:4:{i:0;s:23:"Menurunkan resistivitas";i:1;s:25:"Meningkatkan resistivitas";i:2;s:17:"Tidak berpengaruh";i:3;s:42:"Membuat resistivitas menjadi tak terhingga";}','','Menurunkan resistivitas','What is the impact of shale presence on rock resistivity?','a:4:{i:0;s:21:"Decreases resistivity";i:1;s:21:"Increases resistivity";i:2;s:9:"No effect";i:3;s:26:"Makes resistivity infinite";}','Decreases resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000451','Manakah yang benar mengenai hubungan antara log porositas neutron dan densitas?','option','PFC000000005','Final Test','a:4:{i:0;s:55:"Dapat digunakan untuk mengidentifikasi litologi dan gas";i:1;s:25:"Hanya mengukur volume air";i:2;s:28:"Tidak dipengaruhi oleh shale";i:3;s:33:"Hanya akurat pada batuan karbonat";}','','Dapat digunakan untuk mengidentifikasi litologi dan gas','Which of the following is true regarding the relationship between neutron and density porosity logs?','a:4:{i:0;s:41:"Can be used to identify lithology and gas";i:1;s:26:"Only measures water volume";i:2;s:24:"Is not affected by shale";i:3;s:32:"Only accurate in carbonate rocks";}','Can be used to identify lithology and gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000452','Dalam interpretasi petrofisika, Rw adalah singkatan dari','option','PFC000000005','Final Test','a:4:{i:0;s:24:"Resistivitas air formasi";i:1;s:22:"Resistivitas reservoir";i:2;s:19:"Resistivitas batuan";i:3;s:19:"Resistivitas lumpur";}','','Resistivitas air formasi','In petrophysical interpretation, Rw stands for','a:4:{i:0;s:27:"Formation water resistivity";i:1;s:21:"Reservoir resistivity";i:2;s:16:"Rock resistivity";i:3;s:15:"Mud resistivity";}','Formation water resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000453','Pilih dua metode utama untuk menghitung porositas dari log','multi','PFC000000005','Final Test','a:4:{i:0;s:12:"Log Densitas";i:1;s:11:"Log Neutron";i:2;s:13:"Log Gamma Ray";i:3;s:6:"Log SP";}','','a:2:{i:0;s:12:"Log Densitas";i:1;s:11:"Log Neutron";}','Choose two main methods to calculate porosity from logs','a:4:{i:0;s:11:"Density Log";i:1;s:11:"Neutron Log";i:2;s:13:"Gamma Ray Log";i:3;s:6:"SP Log";}','a:2:{i:0;s:11:"Density Log";i:1;s:11:"Neutron Log";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000454','Apa yang dimaksud dengan zona ''pay''?','option','PFC000000005','Final Test','a:4:{i:0;s:67:"Bagian reservoir yang mampu mengalirkan hidrokarbon secara ekonomis";i:1;s:34:"Zona yang tidak memiliki porositas";i:2;s:26:"Zona yang hanya berisi air";i:3;s:29:"Zona dengan permeabilitas nol";}','','Bagian reservoir yang mampu mengalirkan hidrokarbon secara ekonomis','What is meant by a ''pay'' zone?','a:4:{i:0;s:70:"The part of a reservoir capable of producing hydrocarbons economically";i:1;s:23:"A zone with no porosity";i:2;s:31:"A zone that contains only water";i:3;s:29:"A zone with zero permeability";}','The part of a reservoir capable of producing hydrocarbons economically','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000455','Kenaikan saturasi air (Sw) dalam suatu zona reservoir umumnya mengindikasikan','option','PFC000000005','Final Test','a:4:{i:0;s:38:"Potensi produksi air yang lebih tinggi";i:1;s:27:"Peningkatan cadangan minyak";i:2;s:26:"Batuan menjadi lebih padat";i:3;s:22:"Penurunan volume shale";}','','Potensi produksi air yang lebih tinggi','An increase in water saturation (Sw) in a reservoir zone generally indicates','a:4:{i:0;s:37:"Higher potential for water production";i:1;s:22:"Increased oil reserves";i:2;s:20:"Rock becoming denser";i:3;s:24:"Decrease in shale volume";}','Higher potential for water production','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000456','Analisis zonasi reservoir dilakukan untuk','option','PFC000000005','Final Test','a:4:{i:0;s:81:"Membagi reservoir menjadi unit-unit dengan karakteristik petrofisika yang seragam";i:1;s:33:"Menentukan lokasi pengeboran baru";i:2;s:28:"Menghitung biaya operasional";i:3;s:25:"Menganalisis jenis minyak";}','','Membagi reservoir menjadi unit-unit dengan karakteristik petrofisika yang seragam','Reservoir zonation analysis is performed to','a:4:{i:0;s:74:"Divide the reservoir into units with uniform petrophysical characteristics";i:1;s:32:"Determine new drilling locations";i:2;s:27:"Calculate operational costs";i:3;s:17:"Analyze oil types";}','Divide the reservoir into units with uniform petrophysical characteristics','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000457','Jika nilai Gamma Ray (GR) rendah pada suatu zona, interpretasi litologi yang paling mungkin adalah','option','PFC000000005','Final Test','a:4:{i:0;s:25:"Pasir bersih (clean sand)";i:1;s:5:"Shale";i:2;s:8:"Batubara";i:3;s:15:"Batuan evaporit";}','','Pasir bersih (clean sand)','If the Gamma Ray (GR) value is low in a zone, the most likely lithology interpretation is','a:4:{i:0;s:10:"Clean sand";i:1;s:5:"Shale";i:2;s:4:"Coal";i:3;s:14:"Evaporite rock";}','Clean sand','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000458','Eksponen saturasi (n) dalam persamaan Archie biasanya dianggap bernilai','option','PFC000000005','Final Test','a:4:{i:0;s:1:"2";i:1;s:1:"1";i:2;s:3:"0.5";i:3;s:1:"4";}','','2','The saturation exponent (n) in the Archie equation is typically assumed to be','a:4:{i:0;s:1:"2";i:1;s:1:"1";i:2;s:3:"0.5";i:3;s:1:"4";}','2','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000459','Mengapa kita perlu menghitung volume shale dalam evaluasi reservoir?','multi','PFC000000005','Final Test','a:4:{i:0;s:47:"Karena shale mempengaruhi perhitungan porositas";i:1;s:50:"Karena shale mempengaruhi perhitungan saturasi air";i:2;s:42:"Karena shale selalu mengandung hidrokarbon";i:3;s:39:"Karena shale meningkatkan permeabilitas";}','','a:2:{i:0;s:47:"Karena shale mempengaruhi perhitungan porositas";i:1;s:50:"Karena shale mempengaruhi perhitungan saturasi air";}','Why do we need to calculate shale volume in reservoir evaluation?','a:4:{i:0;s:43:"Because shale affects porosity calculations";i:1;s:51:"Because shale affects water saturation calculations";i:2;s:42:"Because shale always contains hydrocarbons";i:3;s:36:"Because shale increases permeability";}','a:2:{i:0;s:43:"Because shale affects porosity calculations";i:1;s:51:"Because shale affects water saturation calculations";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000460','Apakah definisi dari tekanan kapiler dalam sistem media berpori?','option','PFC000000006','Final Test','a:4:{i:0;s:53:"Perbedaan tekanan antara fase non-wetting dan wetting";i:1;s:53:"Tekanan yang diberikan oleh fluida di dalam reservoir";i:2;s:29:"Tekanan hidrostatik kolom air";i:3;s:42:"Tekanan balik dari formasi saat pengeboran";}','','Perbedaan tekanan antara fase non-wetting dan wetting','What is the definition of capillary pressure in a porous media system?','a:4:{i:0;s:58:"Difference between non-wetting and wetting phase pressures";i:1;s:43:"Pressure exerted by fluids in the reservoir";i:2;s:40:"Hydrostatic pressure of the water column";i:3;s:48:"Back pressure from the formation during drilling";}','Difference between non-wetting and wetting phase pressures','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000461','Metode manakah yang paling umum digunakan untuk mengukur kurva tekanan kapiler di laboratorium?','option','PFC000000006','Final Test','a:4:{i:0;s:17:"Mercury Injection";i:1;s:10:"Centrifuge";i:2;s:12:"Porous Plate";i:3;s:19:"Semua jawaban benar";}','','Semua jawaban benar','Which method is most commonly used to measure capillary pressure curves in the laboratory?','a:4:{i:0;s:17:"Mercury Injection";i:1;s:10:"Centrifuge";i:2;s:12:"Porous Plate";i:3;s:16:"All of the above";}','All of the above','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000462','Faktor apa saja yang mempengaruhi besarnya tekanan kapiler?','multi','PFC000000006','Final Test','a:4:{i:0;s:41:"Tegangan antar muka (interfacial tension)";i:1;s:28:"Sudut kontak (contact angle)";i:2;s:21:"Permeabilitas absolut";i:3;s:16:"Porositas batuan";}','','a:2:{i:0;s:41:"Tegangan antar muka (interfacial tension)";i:1;s:28:"Sudut kontak (contact angle)";}','Which factors influence the magnitude of capillary pressure?','a:4:{i:0;s:19:"Interfacial tension";i:1;s:13:"Contact angle";i:2;s:21:"Absolute permeability";i:3;s:13:"Rock porosity";}','a:2:{i:0;s:19:"Interfacial tension";i:1;s:13:"Contact angle";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000463','Apa yang dimaksud dengan Irreducible Water Saturation (Swi)?','option','PFC000000006','Final Test','a:4:{i:0;s:41:"Saturasi air maksimum yang dapat bergerak";i:1;s:70:"Saturasi air di mana air tidak lagi dapat mengalir karena gaya kapiler";i:2;s:41:"Saturasi air pada saat batuan jenuh total";i:3;s:44:"Saturasi air saat terjadi water breakthrough";}','','Saturasi air di mana air tidak lagi dapat mengalir karena gaya kapiler','What is meant by Irreducible Water Saturation (Swi)?','a:4:{i:0;s:38:"Maximum water saturation that can flow";i:1;s:71:"Water saturation where water can no longer flow due to capillary forces";i:2;s:49:"Water saturation when the rock is fully saturated";i:3;s:38:"Water saturation at water breakthrough";}','Water saturation where water can no longer flow due to capillary forces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000464','Bagaimana hubungan antara ukuran pori dan tekanan kapiler pada batuan reservoir?','option','PFC000000006','Final Test','a:4:{i:0;s:57:"Semakin kecil ukuran pori, semakin tinggi tekanan kapiler";i:1;s:57:"Semakin besar ukuran pori, semakin tinggi tekanan kapiler";i:2;s:46:"Ukuran pori tidak mempengaruhi tekanan kapiler";i:3;s:53:"Tekanan kapiler berbanding lurus dengan diameter pori";}','','Semakin kecil ukuran pori, semakin tinggi tekanan kapiler','What is the relationship between pore size and capillary pressure in reservoir rocks?','a:4:{i:0;s:60:"The smaller the pore size, the higher the capillary pressure";i:1;s:59:"The larger the pore size, the higher the capillary pressure";i:2;s:44:"Pore size does not affect capillary pressure";i:3;s:60:"Capillary pressure is directly proportional to pore diameter";}','The smaller the pore size, the higher the capillary pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000465','Apa yang terjadi pada kurva tekanan kapiler jika batuan bersifat oil-wet?','option','PFC000000006','Final Test','a:4:{i:0;s:31:"Tekanan kapiler menjadi negatif";i:1;s:27:"Tekanan kapiler menjadi nol";i:2;s:33:"Tekanan kapiler meningkat drastis";i:3;s:30:"Tidak ada perubahan pada kurva";}','','Tekanan kapiler menjadi negatif','What happens to the capillary pressure curve if the rock is oil-wet?','a:4:{i:0;s:35:"Capillary pressure becomes negative";i:1;s:31:"Capillary pressure becomes zero";i:2;s:40:"Capillary pressure increases drastically";i:3;s:22:"No change in the curve";}','Capillary pressure becomes negative','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000466','Permeabilitas relatif (kr) adalah rasio antara:','option','PFC000000006','Final Test','a:4:{i:0;s:57:"Permeabilitas efektif fase terhadap permeabilitas absolut";i:1;s:40:"Permeabilitas absolut terhadap porositas";i:2;s:45:"Permeabilitas fase terhadap viskositas fluida";i:3;s:55:"Permeabilitas dua fase terhadap permeabilitas satu fase";}','','Permeabilitas efektif fase terhadap permeabilitas absolut','Relative permeability (kr) is the ratio of:','a:4:{i:0;s:53:"Effective phase permeability to absolute permeability";i:1;s:33:"Absolute permeability to porosity";i:2;s:37:"Phase permeability to fluid viscosity";i:3;s:51:"Two-phase permeability to single-phase permeability";}','Effective phase permeability to absolute permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000467','Apa syarat terjadinya aliran steady-state dalam pengukuran permeabilitas relatif?','option','PFC000000006','Final Test','a:4:{i:0;s:45:"Laju alir fluida konstan dan saturasi konstan";i:1;s:35:"Tekanan berubah-ubah secara drastis";i:2;s:31:"Hanya satu fluida yang mengalir";i:3;s:36:"Saturasi terus berubah seiring waktu";}','','Laju alir fluida konstan dan saturasi konstan','What is the condition for steady-state flow in relative permeability measurement?','a:4:{i:0;s:48:"Constant fluid flow rate and constant saturation";i:1;s:28:"Pressure changes drastically";i:2;s:25:"Only one fluid is flowing";i:3;s:28:"Saturation changes over time";}','Constant fluid flow rate and constant saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000468','Pada titik crossover dari kurva permeabilitas relatif (krw = kro), apa yang biasanya terjadi?','option','PFC000000006','Final Test','a:4:{i:0;s:46:"Saturasi air lebih besar dari 50% jika oil-wet";i:1;s:48:"Saturasi air lebih besar dari 50% jika water-wet";i:2;s:23:"Saturasi air selalu 50%";i:3;s:30:"Saturasi air tidak berpengaruh";}','','Saturasi air lebih besar dari 50% jika oil-wet','At the crossover point of the relative permeability curve (krw = kro), what usually occurs?','a:4:{i:0;s:47:"Water saturation is greater than 50% if oil-wet";i:1;s:49:"Water saturation is greater than 50% if water-wet";i:2;s:30:"Water saturation is always 50%";i:3;s:30:"Water saturation has no effect";}','Water saturation is greater than 50% if oil-wet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000469','Fenomena hysteresis pada kurva tekanan kapiler terjadi karena:','option','PFC000000006','Final Test','a:4:{i:0;s:38:"Perbedaan proses imbibisi dan drainase";i:1;s:40:"Kondisi temperatur reservoir yang tinggi";i:2;s:35:"Komposisi kimia fluida yang berubah";i:3;s:23:"Ketidakhomogenan batuan";}','','Perbedaan proses imbibisi dan drainase','Hysteresis phenomenon in capillary pressure curves occurs due to:','a:4:{i:0;s:52:"Difference between imbibition and drainage processes";i:1;s:37:"High reservoir temperature conditions";i:2;s:35:"Changing fluid chemical composition";i:3;s:18:"Rock heterogeneity";}','Difference between imbibition and drainage processes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000470','Apa yang dimaksud dengan proses drainase pada tekanan kapiler?','option','PFC000000006','Final Test','a:4:{i:0;s:42:"Fase non-wetting menggantikan fase wetting";i:1;s:42:"Fase wetting menggantikan fase non-wetting";i:2;s:33:"Fase air menggantikan fase minyak";i:3;s:35:"Aliran fluida tanpa tekanan kapiler";}','','Fase non-wetting menggantikan fase wetting','What is meant by the drainage process in capillary pressure?','a:4:{i:0;s:40:"Non-wetting phase replaces wetting phase";i:1;s:40:"Wetting phase replaces non-wetting phase";i:2;s:30:"Water phase replaces oil phase";i:3;s:37:"Fluid flow without capillary pressure";}','Non-wetting phase replaces wetting phase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000471','Manakah pernyataan yang benar mengenai wettability batuan?','multi','PFC000000006','Final Test','a:4:{i:0;s:44:"Water-wet memiliki sudut kontak < 90 derajat";i:1;s:42:"Oil-wet memiliki sudut kontak > 90 derajat";i:2;s:52:"Wettability tidak mempengaruhi permeabilitas relatif";i:3;s:59:"Intermediate-wet memiliki sudut kontak mendekati 90 derajat";}','','a:3:{i:0;s:44:"Water-wet memiliki sudut kontak < 90 derajat";i:1;s:42:"Oil-wet memiliki sudut kontak > 90 derajat";i:2;s:59:"Intermediate-wet memiliki sudut kontak mendekati 90 derajat";}','Which statements are true regarding rock wettability?','a:4:{i:0;s:40:"Water-wet has contact angle < 90 degrees";i:1;s:38:"Oil-wet has contact angle > 90 degrees";i:2;s:49:"Wettability does not affect relative permeability";i:3;s:50:"Intermediate-wet has contact angle near 90 degrees";}','a:3:{i:0;s:40:"Water-wet has contact angle < 90 degrees";i:1;s:38:"Oil-wet has contact angle > 90 degrees";i:2;s:50:"Intermediate-wet has contact angle near 90 degrees";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000472','Pada sistem tiga fase (minyak, air, gas), permeabilitas relatif gas (krg) umumnya bergantung pada:','option','PFC000000006','Final Test','a:4:{i:0;s:32:"Saturasi gas dan saturasi minyak";i:1;s:18:"Hanya saturasi gas";i:2;s:18:"Hanya saturasi air";i:3;s:18:"Tekanan overburden";}','','Saturasi gas dan saturasi minyak','In a three-phase system (oil, water, gas), the relative permeability of gas (krg) generally depends on:','a:4:{i:0;s:33:"Gas saturation and oil saturation";i:1;s:19:"Only gas saturation";i:2;s:21:"Only water saturation";i:3;s:19:"Overburden pressure";}','Gas saturation and oil saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000473','Apa dampak utama dari peningkatan tegangan antar muka terhadap perolehan minyak?','option','PFC000000006','Final Test','a:4:{i:0;s:50:"Menurunkan perolehan minyak karena jebakan kapiler";i:1;s:29:"Meningkatkan perolehan minyak";i:2;s:39:"Tidak berpengaruh pada perolehan minyak";i:3;s:25:"Mempercepat laju alir air";}','','Menurunkan perolehan minyak karena jebakan kapiler','What is the main impact of increased interfacial tension on oil recovery?','a:4:{i:0;s:48:"Decreases oil recovery due to capillary trapping";i:1;s:22:"Increases oil recovery";i:2;s:25:"No effect on oil recovery";i:3;s:25:"Speeds up water flow rate";}','Decreases oil recovery due to capillary trapping','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000474','Metode mercury injection adalah jenis tes:','option','PFC000000006','Final Test','a:4:{i:0;s:8:"Drainase";i:1;s:8:"Imbibisi";i:2;s:22:"Spontaneous imbibition";i:3;s:17:"Steady-state flow";}','','Drainase','The mercury injection method is a type of:','a:4:{i:0;s:8:"Drainage";i:1;s:10:"Imbibition";i:2;s:22:"Spontaneous imbibition";i:3;s:17:"Steady-state flow";}','Drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000475','Mengapa kurva permeabilitas relatif penting dalam simulasi reservoir?','option','PFC000000006','Final Test','a:4:{i:0;s:44:"Untuk memprediksi perilaku aliran multi-fase";i:1;s:35:"Untuk menghitung tekanan overburden";i:2;s:33:"Untuk menentukan porositas batuan";i:3;s:30:"Untuk mengukur densitas minyak";}','','Untuk memprediksi perilaku aliran multi-fase','Why are relative permeability curves important in reservoir simulation?','a:4:{i:0;s:36:"To predict multi-phase flow behavior";i:1;s:32:"To calculate overburden pressure";i:2;s:26:"To determine rock porosity";i:3;s:22:"To measure oil density";}','To predict multi-phase flow behavior','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000476','Faktor apa yang menyebabkan harga krw (permeabilitas relatif air) mencapai nilai maksimal?','option','PFC000000006','Final Test','a:4:{i:0;s:40:"Saturasi air mendekati 100% (atau 1-Sor)";i:1;s:25:"Saturasi air mendekati 0%";i:2;s:29:"Tekanan kapiler sangat tinggi";i:3;s:25:"Permeabilitas absolut nol";}','','Saturasi air mendekati 100% (atau 1-Sor)','What factor causes the krw (relative water permeability) value to reach its maximum?','a:4:{i:0;s:43:"Water saturation approaches 100% (or 1-Sor)";i:1;s:30:"Water saturation approaches 0%";i:2;s:28:"Very high capillary pressure";i:3;s:26:"Zero absolute permeability";}','Water saturation approaches 100% (or 1-Sor)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000477','Dalam konteks reservoir, apa arti dari ''Water-wet''?','option','PFC000000006','Final Test','a:4:{i:0;s:41:"Batuan lebih menyukai air daripada minyak";i:1;s:41:"Batuan lebih menyukai minyak daripada air";i:2;s:45:"Permukaan batuan tidak bereaksi dengan fluida";i:3;s:23:"Batuan sangat kedap air";}','','Batuan lebih menyukai air daripada minyak','In the context of reservoirs, what does ''Water-wet'' mean?','a:4:{i:0;s:27:"Rock prefers water over oil";i:1;s:27:"Rock prefers oil over water";i:2;s:39:"Rock surface does not react with fluids";i:3;s:24:"Rock is very water-tight";}','Rock prefers water over oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000478','Manakah yang benar tentang karakteristik kurva permeabilitas relatif pada kondisi water-wet?','option','PFC000000006','Final Test','a:4:{i:0;s:51:"Kurva krw cenderung rendah pada saturasi air rendah";i:1;s:51:"Kurva krw cenderung tinggi pada saturasi air rendah";i:2;s:38:"Kurva kro selalu lebih tinggi dari krw";i:3;s:42:"Tidak ada hubungan antara krw dan saturasi";}','','Kurva krw cenderung rendah pada saturasi air rendah','Which is true about the characteristics of relative permeability curves under water-wet conditions?','a:4:{i:0;s:49:"krw curve tends to be low at low water saturation";i:1;s:50:"krw curve tends to be high at low water saturation";i:2;s:35:"kro curve is always higher than krw";i:3;s:42:"No relationship between krw and saturation";}','krw curve tends to be low at low water saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000479','Apa kegunaan utama data tekanan kapiler (Pc) dalam evaluasi formasi?','multi','PFC000000006','Final Test','a:4:{i:0;s:62:"Estimasi saturasi air pada ketinggian di atas free water level";i:1;s:23:"Penentuan zona transisi";i:2;s:33:"Perhitungan permeabilitas absolut";i:3;s:28:"Estimasi tinggi kolom minyak";}','','a:3:{i:0;s:62:"Estimasi saturasi air pada ketinggian di atas free water level";i:1;s:23:"Penentuan zona transisi";i:2;s:28:"Estimasi tinggi kolom minyak";}','What is the primary use of capillary pressure (Pc) data in formation evaluation?','a:4:{i:0;s:53:"Estimation of water saturation above free water level";i:1;s:32:"Determination of transition zone";i:2;s:36:"Calculation of absolute permeability";i:3;s:31:"Estimation of oil column height";}','a:3:{i:0;s:53:"Estimation of water saturation above free water level";i:1;s:32:"Determination of transition zone";i:2;s:31:"Estimation of oil column height";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000480','Parameter utama yang diperlukan untuk menghitung Original Oil In Place (OOIP) secara volumetrik adalah...','multi','PFC000000007','Final Test','a:4:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:18:"Volume bulk batuan";i:3;s:15:"Tekanan formasi";}','','a:3:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:18:"Volume bulk batuan";}','The main parameters required to calculate Original Oil In Place (OOIP) volumetrically are...','a:4:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:16:"Bulk rock volume";i:3;s:18:"Formation pressure";}','a:3:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:16:"Bulk rock volume";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000481','Apa dampak utama dari keterbatasan data log dalam estimasi volume cadangan?','option','PFC000000007','Final Test','a:4:{i:0;s:49:"Meningkatkan tingkat ketidakpastian (uncertainty)";i:1;s:27:"Mempercepat waktu pelaporan";i:2;s:38:"Menghilangkan kebutuhan akan core data";i:3;s:27:"Mengurangi biaya eksplorasi";}','','Meningkatkan tingkat ketidakpastian (uncertainty)','What is the main impact of limited log data on reserve volume estimation?','a:4:{i:0;s:28:"Increases uncertainty levels";i:1;s:24:"Speeds up reporting time";i:2;s:33:"Eliminates the need for core data";i:3;s:25:"Reduces exploration costs";}','Increases uncertainty levels','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000482','Integrasi data petrofisika dengan model geologi bertujuan untuk...','option','PFC000000007','Final Test','a:4:{i:0;s:49:"Mendefinisikan distribusi heterogenitas reservoir";i:1;s:30:"Menentukan harga minyak mentah";i:2;s:28:"Menggantikan peran geofisika";i:3;s:22:"Mempercepat pengeboran";}','','Mendefinisikan distribusi heterogenitas reservoir','Integrating petrophysical data with geological models aims to...','a:4:{i:0;s:43:"Define reservoir heterogeneity distribution";i:1;s:26:"Determine crude oil prices";i:2;s:30:"Replace the role of geophysics";i:3;s:19:"Accelerate drilling";}','Define reservoir heterogeneity distribution','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000483','Dalam konteks pelaporan cadangan, istilah ''lead time'' merujuk pada...','option','PFC000000007','Final Test','a:4:{i:0;s:45:"Waktu dari penemuan hingga produksi komersial";i:1;s:35:"Waktu yang dibutuhkan untuk logging";i:2;s:35:"Waktu proses pengolahan data mentah";i:3;s:35:"Waktu tunggu hasil uji laboratorium";}','','Waktu dari penemuan hingga produksi komersial','In the context of reserve reporting, the term ''lead time'' refers to...','a:4:{i:0;s:44:"Time from discovery to commercial production";i:1;s:25:"Time required for logging";i:2;s:24:"Raw data processing time";i:3;s:35:"Waiting time for laboratory results";}','Time from discovery to commercial production','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000484','Faktor apa yang dapat menyebabkan kesalahan sistematis dalam estimasi OOIP?','multi','PFC000000007','Final Test','a:4:{i:0;s:45:"Kesalahan penentuan batas kontak fluida (OWC)";i:1;s:39:"Penggunaan parameter m yang tidak tepat";i:2;s:30:"Kualitas lubang bor yang buruk";i:3;s:21:"Kenaikan harga minyak";}','','a:3:{i:0;s:45:"Kesalahan penentuan batas kontak fluida (OWC)";i:1;s:39:"Penggunaan parameter m yang tidak tepat";i:2;s:30:"Kualitas lubang bor yang buruk";}','What factors can cause systematic errors in OOIP estimation?','a:4:{i:0;s:42:"Error in fluid contact determination (OWC)";i:1;s:27:"Incorrect m parameter usage";i:2;s:21:"Poor borehole quality";i:3;s:18:"Rise in oil prices";}','a:3:{i:0;s:42:"Error in fluid contact determination (OWC)";i:1;s:27:"Incorrect m parameter usage";i:2;s:21:"Poor borehole quality";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000485','Mengapa korelasi data inti (core) sangat penting dalam estimasi petrofisika?','option','PFC000000007','Final Test','a:4:{i:0;s:35:"Untuk kalibrasi parameter model log";i:1;s:34:"Untuk menghitung biaya operasional";i:2;s:27:"Untuk menentukan lokasi rig";i:3;s:32:"Untuk estimasi viskositas minyak";}','','Untuk kalibrasi parameter model log','Why is core data correlation crucial in petrophysical estimation?','a:4:{i:0;s:33:"To calibrate log model parameters";i:1;s:30:"To calculate operational costs";i:2;s:25:"To determine rig location";i:3;s:25:"To estimate oil viscosity";}','To calibrate log model parameters','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000486','Jika saturasi air (Sw) diabaikan dalam perhitungan cadangan, maka estimasi OOIP akan menjadi...','option','PFC000000007','Final Test','a:4:{i:0;s:12:"Overestimasi";i:1;s:13:"Underestimasi";i:2;s:10:"Tetap sama";i:3;s:17:"Tidak terpengaruh";}','','Overestimasi','If water saturation (Sw) is ignored in reserve calculation, the OOIP estimate will be...','a:4:{i:0;s:13:"Overestimated";i:1;s:14:"Underestimated";i:2;s:16:"Remains the same";i:3;s:10:"Unaffected";}','Overestimated','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000487','Apa fungsi utama dari integrasi data petrofisika dalam pengembangan lapangan?','option','PFC000000007','Final Test','a:4:{i:0;s:34:"Optimasi strategi penempatan sumur";i:1;s:25:"Menentukan pajak produksi";i:2;s:37:"Meningkatkan kualitas pipa distribusi";i:3;s:26:"Mengatur jam kerja kru rig";}','','Optimasi strategi penempatan sumur','What is the primary function of integrating petrophysical data in field development?','a:4:{i:0;s:41:"Optimization of well placement strategies";i:1;s:28:"Determining production taxes";i:2;s:35:"Improving distribution pipe quality";i:3;s:33:"Regulating rig crew working hours";}','Optimization of well placement strategies','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000488','Data petrofisika apa yang paling krusial untuk menentukan batas ''Net Pay''?','multi','PFC000000007','Final Test','a:4:{i:0;s:17:"Cut-off porositas";i:1;s:20:"Cut-off saturasi air";i:2;s:12:"Volume shale";i:3;s:20:"Kecepatan pengeboran";}','','a:3:{i:0;s:17:"Cut-off porositas";i:1;s:20:"Cut-off saturasi air";i:2;s:12:"Volume shale";}','Which petrophysical data is most crucial for determining the ''Net Pay'' boundary?','a:4:{i:0;s:16:"Porosity cut-off";i:1;s:24:"Water saturation cut-off";i:2;s:12:"Shale volume";i:3;s:14:"Drilling speed";}','a:3:{i:0;s:16:"Porosity cut-off";i:1;s:24:"Water saturation cut-off";i:2;s:12:"Shale volume";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000489','Apa yang dimaksud dengan ''Net-to-Gross'' ratio dalam estimasi volume?','option','PFC000000007','Final Test','a:4:{i:0;s:75:"Perbandingan ketebalan reservoir produktif terhadap total ketebalan formasi";i:1;s:48:"Perbandingan minyak terhadap gas dalam reservoir";i:2;s:45:"Perbandingan porositas terhadap permeabilitas";i:3;s:32:"Perbandingan air terhadap minyak";}','','Perbandingan ketebalan reservoir produktif terhadap total ketebalan formasi','What is meant by the ''Net-to-Gross'' ratio in volume estimation?','a:4:{i:0;s:68:"Ratio of productive reservoir thickness to total formation thickness";i:1;s:36:"Ratio of oil to gas in the reservoir";i:2;s:33:"Ratio of porosity to permeability";i:3;s:21:"Ratio of water to oil";}','Ratio of productive reservoir thickness to total formation thickness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000490','Bagaimana keterbatasan data petrofisika di zona eksplorasi mempengaruhi pelaporan cadangan?','option','PFC000000007','Final Test','a:4:{i:0;s:66:"Menurunkan klasifikasi cadangan menjadi ''Probable'' atau ''Possible''";i:1;s:32:"Langsung menghentikan pengeboran";i:2;s:33:"Meningkatkan nilai ekonomi proyek";i:3;s:28:"Menyederhanakan model statis";}','','Menurunkan klasifikasi cadangan menjadi ''Probable'' atau ''Possible''','How does limited petrophysical data in exploration zones affect reserve reporting?','a:4:{i:0;s:61:"Downgrades reserve classification to ''Probable'' or ''Possible''";i:1;s:26:"Immediately stops drilling";i:2;s:32:"Increases project economic value";i:3;s:27:"Simplifies the static model";}','Downgrades reserve classification to ''Probable'' or ''Possible''','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000491','Manakah pernyataan yang benar mengenai pengaruh variasi litologi terhadap estimasi volume?','option','PFC000000007','Final Test','a:4:{i:0;s:63:"Perubahan litologi mempengaruhi respon log dan parameter Archie";i:1;s:47:"Litologi tidak berpengaruh pada estimasi volume";i:2;s:47:"Estimasi volume hanya bergantung pada porositas";i:3;s:41:"Litologi hanya dihitung dari data seismik";}','','Perubahan litologi mempengaruhi respon log dan parameter Archie','Which statement is correct regarding the effect of lithology variation on volume estimation?','a:4:{i:0;s:59:"Lithology changes affect log response and Archie parameters";i:1;s:44:"Lithology has no effect on volume estimation";i:2;s:42:"Volume estimation depends only on porosity";i:3;s:46:"Lithology is calculated only from seismic data";}','Lithology changes affect log response and Archie parameters','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000492','Dalam pelaporan cadangan, mengapa audit data petrofisika diperlukan?','option','PFC000000007','Final Test','a:4:{i:0;s:55:"Untuk menjamin akurasi dan kredibilitas volume cadangan";i:1;s:28:"Untuk mengurangi beban pajak";i:2;s:36:"Untuk mempercepat penyusunan laporan";i:3;s:37:"Untuk mengganti tenaga ahli eksternal";}','','Untuk menjamin akurasi dan kredibilitas volume cadangan','In reserve reporting, why is a petrophysical data audit necessary?','a:4:{i:0;s:53:"To ensure accuracy and credibility of reserve volumes";i:1;s:20:"To reduce tax burden";i:2;s:32:"To accelerate report preparation";i:3;s:27:"To replace external experts";}','To ensure accuracy and credibility of reserve volumes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000493','Apa peran utama log resistivitas dalam aplikasi perhitungan cadangan?','option','PFC000000007','Final Test','a:4:{i:0;s:30:"Membantu estimasi saturasi air";i:1;s:32:"Membantu estimasi volume lempung";i:2;s:32:"Menentukan kedalaman total sumur";i:3;s:33:"Membantu estimasi densitas batuan";}','','Membantu estimasi saturasi air','What is the main role of resistivity logs in reserve calculation applications?','a:4:{i:0;s:38:"Assists in water saturation estimation";i:1;s:34:"Assists in shale volume estimation";i:2;s:27:"Determines total well depth";i:3;s:34:"Assists in rock density estimation";}','Assists in water saturation estimation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000494','Kapan data petrofisika harus diintegrasikan dengan data seismik?','option','PFC000000007','Final Test','a:4:{i:0;s:52:"Saat membangun model statis 3D untuk estimasi volume";i:1;s:31:"Hanya setelah sumur berproduksi";i:2;s:32:"Hanya saat melakukan survei awal";i:3;s:31:"Setelah pelaporan akhir selesai";}','','Saat membangun model statis 3D untuk estimasi volume','When should petrophysical data be integrated with seismic data?','a:4:{i:0;s:53:"When building a 3D static model for volume estimation";i:1;s:36:"Only after the well is in production";i:2;s:40:"Only when conducting preliminary surveys";i:3;s:34:"After final reporting is completed";}','When building a 3D static model for volume estimation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000495','Apa risiko utama jika estimasi OOIP dilakukan tanpa mempertimbangkan heterogenitas reservoir?','option','PFC000000007','Final Test','a:4:{i:0;s:40:"Pola aliran fluida akan salah diprediksi";i:1;s:39:"Biaya operasional menjadi terlalu murah";i:2;s:48:"Tekanan reservoir akan meningkat secara otomatis";i:3;s:33:"Data geologi menjadi lebih akurat";}','','Pola aliran fluida akan salah diprediksi','What is the main risk if OOIP estimation is performed without considering reservoir heterogeneity?','a:4:{i:0;s:49:"Fluid flow patterns will be incorrectly predicted";i:1;s:34:"Operational costs become too cheap";i:2;s:46:"Reservoir pressure will increase automatically";i:3;s:37:"Geological data becomes more accurate";}','Fluid flow patterns will be incorrectly predicted','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000496','Untuk apa ''Formation Factor'' (F) digunakan dalam aplikasi petrofisika?','option','PFC000000007','Final Test','a:4:{i:0;s:50:"Menghubungkan porositas dengan resistivitas batuan";i:1;s:32:"Menghitung permeabilitas absolut";i:2;s:28:"Menentukan viskositas minyak";i:3;s:24:"Mengukur tekanan kapiler";}','','Menghubungkan porositas dengan resistivitas batuan','What is the ''Formation Factor'' (F) used for in petrophysical applications?','a:4:{i:0;s:37:"Relating porosity to rock resistivity";i:1;s:33:"Calculating absolute permeability";i:2;s:25:"Determining oil viscosity";i:3;s:28:"Measuring capillary pressure";}','Relating porosity to rock resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000497','Manakah di antara berikut yang merupakan keterbatasan umum data logging?','multi','PFC000000007','Final Test','a:4:{i:0;s:52:"Kedalaman penyelidikan alat (depth of investigation)";i:1;s:22:"Resolusi vertikal alat";i:2;s:31:"Gangguan dari lumpur pengeboran";i:3;s:24:"Ketersediaan tenaga ahli";}','','a:3:{i:0;s:52:"Kedalaman penyelidikan alat (depth of investigation)";i:1;s:22:"Resolusi vertikal alat";i:2;s:31:"Gangguan dari lumpur pengeboran";}','Which of the following are common limitations of logging data?','a:4:{i:0;s:22:"Depth of investigation";i:1;s:24:"Tool vertical resolution";i:2;s:30:"Interference from drilling mud";i:3;s:19:"Expert availability";}','a:3:{i:0;s:22:"Depth of investigation";i:1;s:24:"Tool vertical resolution";i:2;s:30:"Interference from drilling mud";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000498','Mengapa pengujian laboratorium (core analysis) tetap penting meskipun ada data log canggih?','option','PFC000000007','Final Test','a:4:{i:0;s:53:"Sebagai dasar kalibrasi ''ground truth'' untuk data log";i:1;s:40:"Untuk menggantikan fungsi log sepenuhnya";i:2;s:37:"Untuk mempercantik presentasi laporan";i:3;s:30:"Karena biaya log terlalu murah";}','','Sebagai dasar kalibrasi ''ground truth'' untuk data log','Why is laboratory testing (core analysis) still important despite advanced log data?','a:4:{i:0;s:50:"As a ''ground truth'' calibration basis for log data";i:1;s:33:"To replace log functions entirely";i:2;s:31:"To enhance report presentations";i:3;s:31:"Because log costs are too cheap";}','As a ''ground truth'' calibration basis for log data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000499','Pelaporan cadangan yang transparan harus mencakup hal berikut...','multi','PFC000000007','Final Test','a:4:{i:0;s:22:"Metodologi perhitungan";i:1;s:19:"Asumsi-asumsi dasar";i:2;s:21:"Analisis sensitivitas";i:3;s:23:"Nama staf pengolah data";}','','a:3:{i:0;s:22:"Metodologi perhitungan";i:1;s:19:"Asumsi-asumsi dasar";i:2;s:21:"Analisis sensitivitas";}','Transparent reserve reporting must include the following...','a:4:{i:0;s:23:"Calculation methodology";i:1;s:17:"Basic assumptions";i:2;s:20:"Sensitivity analysis";i:3;s:27:"Data processing staff names";}','a:3:{i:0;s:23:"Calculation methodology";i:1;s:17:"Basic assumptions";i:2;s:20:"Sensitivity analysis";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000500','Manakah dari tahapan produksi berikut yang mengandalkan energi alami reservoir untuk memproduksikan minyak?','option','PFC000000008','Final Test','a:4:{i:0;s:16:"Primary recovery";i:1;s:18:"Secondary recovery";i:2;s:17:"Tertiary recovery";i:3;s:10:"EOR termal";}','','Primary recovery','Which of the following production stages relies on natural reservoir energy to produce oil?','a:4:{i:0;s:16:"Primary recovery";i:1;s:18:"Secondary recovery";i:2;s:17:"Tertiary recovery";i:3;s:11:"Thermal EOR";}','Primary recovery','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000501','Faktor perolehan minyak (Recovery Factor) dipengaruhi oleh parameter fisik berikut:','multi','PFC000000008','Final Test','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:17:"Viskositas fluida";i:3;s:15:"Kedalaman sumur";}','','a:3:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:17:"Viskositas fluida";}','Oil recovery factor is influenced by the following physical parameters:','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:15:"Fluid viscosity";i:3;s:10:"Well depth";}','a:3:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:15:"Fluid viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000502','Metode secondary recovery yang paling umum diterapkan di lapangan minyak adalah:','option','PFC000000008','Final Test','a:4:{i:0;s:15:"Injeksi gas CO2";i:1;s:13:"Waterflooding";i:2;s:14:"Steam flooding";i:3;s:15:"Injeksi polimer";}','','Waterflooding','The most common secondary recovery method applied in oil fields is:','a:4:{i:0;s:17:"CO2 gas injection";i:1;s:13:"Waterflooding";i:2;s:14:"Steam flooding";i:3;s:17:"Polymer injection";}','Waterflooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000503','Apa tujuan utama dari penerapan metode Enhanced Oil Recovery (EOR)?','option','PFC000000008','Final Test','a:4:{i:0;s:28:"Mengurangi biaya operasional";i:1;s:53:"Meningkatkan perolehan minyak setelah tahap secondary";i:2;s:39:"Mempercepat penurunan tekanan reservoir";i:3;s:36:"Menggantikan penggunaan pompa angguk";}','','Meningkatkan perolehan minyak setelah tahap secondary','What is the main objective of applying Enhanced Oil Recovery (EOR) methods?','a:4:{i:0;s:24:"Reduce operational costs";i:1;s:47:"Increase oil recovery after the secondary stage";i:2;s:37:"Accelerate reservoir pressure decline";i:3;s:24:"Replace sucker rod pumps";}','Increase oil recovery after the secondary stage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000504','Mekanisme pendorong utama pada tahap primary recovery meliputi:','multi','PFC000000008','Final Test','a:4:{i:0;s:21:"Ekspansi gas terlarut";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";i:3;s:11:"Injeksi uap";}','','a:3:{i:0;s:21:"Ekspansi gas terlarut";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";}','Primary recovery drive mechanisms include:','a:4:{i:0;s:19:"Dissolved gas drive";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";i:3;s:15:"Steam injection";}','a:3:{i:0;s:19:"Dissolved gas drive";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000505','Metode EOR yang bekerja dengan cara menurunkan interfacial tension (IFT) antara minyak dan air adalah:','option','PFC000000008','Final Test','a:4:{i:0;s:13:"Injeksi steam";i:1;s:30:"Chemical flooding (surfactant)";i:2;s:22:"Injeksi gas immiscible";i:3;s:15:"Injeksi polimer";}','','Chemical flooding (surfactant)','An EOR method that works by reducing the interfacial tension (IFT) between oil and water is:','a:4:{i:0;s:15:"Steam injection";i:1;s:30:"Chemical flooding (surfactant)";i:2;s:24:"Immiscible gas injection";i:3;s:17:"Polymer injection";}','Chemical flooding (surfactant)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000506','Pada metode EOR termal, penurunan viskositas minyak terjadi karena:','option','PFC000000008','Final Test','a:4:{i:0;s:19:"Peningkatan tekanan";i:1;s:22:"Peningkatan temperatur";i:2;s:20:"Penambahan surfaktan";i:3;s:16:"Perubahan pH air";}','','Peningkatan temperatur','In thermal EOR methods, the decrease in oil viscosity occurs due to:','a:4:{i:0;s:17:"Pressure increase";i:1;s:20:"Temperature increase";i:2;s:19:"Surfactant addition";i:3;s:15:"Water pH change";}','Temperature increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000507','Apa yang dimaksud dengan residual oil saturation (Sor)?','option','PFC000000008','Final Test','a:4:{i:0;s:40:"Minyak yang tersisa setelah produksi EOR";i:1;s:30:"Minyak awal di dalam reservoir";i:2;s:57:"Minyak yang tidak dapat diproduksi secara teknis/ekonomis";i:3;s:34:"Minyak yang mengalir ke lubang bor";}','','Minyak yang tidak dapat diproduksi secara teknis/ekonomis','What is meant by residual oil saturation (Sor)?','a:4:{i:0;s:34:"Oil remaining after EOR production";i:1;s:28:"Initial oil in the reservoir";i:2;s:52:"Oil that cannot be technically/economically produced";i:3;s:27:"Oil flowing to the wellbore";}','Oil that cannot be technically/economically produced','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000508','Manakah pernyataan yang benar mengenai polymer flooding?','option','PFC000000008','Final Test','a:4:{i:0;s:58:"Menurunkan viskositas air untuk memperbaiki mobility ratio";i:1;s:60:"Meningkatkan viskositas air untuk memperbaiki mobility ratio";i:2;s:32:"Menurunkan IFT secara signifikan";i:3;s:23:"Menguapkan minyak berat";}','','Meningkatkan viskositas air untuk memperbaiki mobility ratio','Which statement is true regarding polymer flooding?','a:4:{i:0;s:49:"Reduces water viscosity to improve mobility ratio";i:1;s:51:"Increases water viscosity to improve mobility ratio";i:2;s:25:"Significantly reduces IFT";i:3;s:19:"Vaporizes heavy oil";}','Increases water viscosity to improve mobility ratio','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000509','Karakteristik reservoir yang tidak mendukung keberhasilan proyek EOR adalah:','option','PFC000000008','Final Test','a:4:{i:0;s:20:"Heterogenitas tinggi";i:1;s:20:"Permeabilitas tinggi";i:2;s:23:"Kontinuitas batuan baik";i:3;s:16:"Porositas tinggi";}','','Heterogenitas tinggi','A reservoir characteristic that does not support the success of an EOR project is:','a:4:{i:0;s:18:"High heterogeneity";i:1;s:17:"High permeability";i:2;s:20:"Good rock continuity";i:3;s:13:"High porosity";}','High heterogeneity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000510','Metode EOR diklasifikasikan berdasarkan mekanisme utamanya menjadi:','multi','PFC000000008','Final Test','a:4:{i:0;s:7:"Thermal";i:1;s:8:"Chemical";i:2;s:12:"Miscible/Gas";i:3;s:7:"Gravity";}','','a:3:{i:0;s:7:"Thermal";i:1;s:8:"Chemical";i:2;s:12:"Miscible/Gas";}','EOR methods are classified based on their main mechanisms into:','a:4:{i:0;s:7:"Thermal";i:1;s:8:"Chemical";i:2;s:12:"Miscible/Gas";i:3;s:7:"Gravity";}','a:3:{i:0;s:7:"Thermal";i:1;s:8:"Chemical";i:2;s:12:"Miscible/Gas";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000511','Tekanan kapiler (Pc) dalam reservoir minyak dipengaruhi oleh:','option','PFC000000008','Final Test','a:4:{i:0;s:53:"Interfacial tension, sudut kontak, dan jari-jari pori";i:1;s:23:"Hanya viskositas minyak";i:2;s:27:"Hanya kecepatan alir fluida";i:3;s:22:"Hanya porositas batuan";}','','Interfacial tension, sudut kontak, dan jari-jari pori','Capillary pressure (Pc) in oil reservoirs is influenced by:','a:4:{i:0;s:51:"Interfacial tension, contact angle, and pore radius";i:1;s:18:"Only oil viscosity";i:2;s:24:"Only fluid flow velocity";i:3;s:18:"Only rock porosity";}','Interfacial tension, contact angle, and pore radius','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000512','Apa dampak negatif dari fenomena fingering pada proses injeksi?','option','PFC000000008','Final Test','a:4:{i:0;s:28:"Peningkatan perolehan minyak";i:1;s:68:"Terobosan (breakthrough) fluida injeksi ke sumur produksi lebih awal";i:2;s:27:"Peningkatan saturasi minyak";i:3;s:24:"Penurunan viskositas air";}','','Terobosan (breakthrough) fluida injeksi ke sumur produksi lebih awal','What is the negative impact of the fingering phenomenon in injection processes?','a:4:{i:0;s:22:"Increased oil recovery";i:1;s:56:"Early breakthrough of injection fluid to production well";i:2;s:24:"Increased oil saturation";i:3;s:25:"Decreased water viscosity";}','Early breakthrough of injection fluid to production well','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000513','Injeksi gas CO2 dapat dikategorikan sebagai:','option','PFC000000008','Final Test','a:4:{i:0;s:16:"Thermal recovery";i:1;s:38:"Miscible atau immiscible gas injection";i:2;s:17:"Chemical recovery";i:3;s:16:"Primary recovery";}','','Miscible atau immiscible gas injection','CO2 gas injection can be categorized as:','a:4:{i:0;s:16:"Thermal recovery";i:1;s:36:"Miscible or immiscible gas injection";i:2;s:17:"Chemical recovery";i:3;s:16:"Primary recovery";}','Miscible or immiscible gas injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000514','Faktor perolehan (RF) didefinisikan sebagai:','option','PFC000000008','Final Test','a:4:{i:0;s:71:"Perbandingan minyak yang diproduksi dengan minyak awal di tempat (OOIP)";i:1;s:27:"Laju produksi harian minyak";i:2;s:27:"Volume pori total reservoir";i:3;s:42:"Tekanan reservoir dibagi tekanan permukaan";}','','Perbandingan minyak yang diproduksi dengan minyak awal di tempat (OOIP)','Recovery factor (RF) is defined as:','a:4:{i:0;s:53:"Ratio of produced oil to original oil in place (OOIP)";i:1;s:25:"Daily oil production rate";i:2;s:27:"Total reservoir pore volume";i:3;s:46:"Reservoir pressure divided by surface pressure";}','Ratio of produced oil to original oil in place (OOIP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000515','Metode EOR mana yang paling efektif untuk minyak berat (heavy oil)?','option','PFC000000008','Final Test','a:4:{i:0;s:16:"Polymer flooding";i:1;s:14:"Steam flooding";i:2;s:19:"Surfactant flooding";i:3;s:13:"Gas injection";}','','Steam flooding','Which EOR method is most effective for heavy oil?','a:4:{i:0;s:16:"Polymer flooding";i:1;s:14:"Steam flooding";i:2;s:19:"Surfactant flooding";i:3;s:13:"Gas injection";}','Steam flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000516','Apa itu mobility ratio (M) dalam konteks pendesakan fluida?','option','PFC000000008','Final Test','a:4:{i:0;s:60:"Rasio mobilitas fluida pendesak terhadap fluida yang didesak";i:1;s:47:"Rasio viskositas minyak terhadap viskositas air";i:2;s:45:"Rasio permeabilitas relatif terhadap saturasi";i:3;s:32:"Rasio tekanan terhadap kedalaman";}','','Rasio mobilitas fluida pendesak terhadap fluida yang didesak','What is the mobility ratio (M) in the context of fluid displacement?','a:4:{i:0;s:62:"Ratio of displacing fluid mobility to displaced fluid mobility";i:1;s:41:"Ratio of oil viscosity to water viscosity";i:2;s:44:"Ratio of relative permeability to saturation";i:3;s:26:"Ratio of pressure to depth";}','Ratio of displacing fluid mobility to displaced fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000517','Parameter utama yang diubah oleh surfaktan untuk meningkatkan perolehan minyak adalah:','option','PFC000000008','Final Test','a:4:{i:0;s:14:"Viskositas air";i:1;s:25:"Interfacial tension (IFT)";i:2;s:15:"Densitas batuan";i:3;s:17:"Tekanan reservoir";}','','Interfacial tension (IFT)','The main parameter modified by surfactants to improve oil recovery is:','a:4:{i:0;s:15:"Water viscosity";i:1;s:25:"Interfacial tension (IFT)";i:2;s:12:"Rock density";i:3;s:18:"Reservoir pressure";}','Interfacial tension (IFT)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000518','Kapan waktu yang tepat untuk memulai secondary recovery?','option','PFC000000008','Final Test','a:4:{i:0;s:32:"Segera setelah penemuan lapangan";i:1;s:70:"Saat tekanan reservoir turun di bawah tekanan gelembung (bubble point)";i:2;s:47:"Setelah produksi primer mencapai batas ekonomis";i:3;s:35:"Setelah reservoir kosong sepenuhnya";}','','Setelah produksi primer mencapai batas ekonomis','When is the right time to start secondary recovery?','a:4:{i:0;s:33:"Immediately after field discovery";i:1;s:57:"When reservoir pressure drops below bubble point pressure";i:2;s:47:"After primary production reaches economic limit";i:3;s:39:"After the reservoir is completely empty";}','After primary production reaches economic limit','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000519','Manakah yang termasuk dalam kategori EOR?','multi','PFC000000008','Final Test','a:4:{i:0;s:15:"Injeksi polimer";i:1;s:13:"Waterflooding";i:2;s:11:"Injeksi uap";i:3;s:17:"Injeksi surfaktan";}','','a:3:{i:0;s:15:"Injeksi polimer";i:1;s:11:"Injeksi uap";i:2;s:17:"Injeksi surfaktan";}','Which of the following are categorized as EOR?','a:4:{i:0;s:17:"Polymer injection";i:1;s:13:"Waterflooding";i:2;s:15:"Steam injection";i:3;s:20:"Surfactant injection";}','a:3:{i:0;s:17:"Polymer injection";i:1;s:15:"Steam injection";i:2;s:20:"Surfactant injection";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000520','Apa fungsi utama penambahan polimer ke dalam fluida injeksi pada proses Chemical EOR?','option','PFC000000009','Final Test','a:4:{i:0;s:35:"Meningkatkan viskositas air injeksi";i:1;s:30:"Menurunkan tegangan antar muka";i:2;s:25:"Mengubah kebasahan batuan";i:3;s:34:"Meningkatkan permeabilitas absolut";}','','Meningkatkan viskositas air injeksi','What is the primary function of adding polymer to the injection fluid in a Chemical EOR process?','a:4:{i:0;s:34:"Increase injection water viscosity";i:1;s:26:"Reduce interfacial tension";i:2;s:22:"Alter rock wettability";i:3;s:30:"Increase absolute permeability";}','Increase injection water viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000521','Parameter apa yang secara langsung dipengaruhi oleh penurunan mobilitas air injeksi melalui polimer flooding?','option','PFC000000009','Final Test','a:4:{i:0;s:21:"Permeabilitas relatif";i:1;s:14:"Mobility ratio";i:2;s:16:"Porositas batuan";i:3;s:15:"Tekanan kapiler";}','','Mobility ratio','Which parameter is directly affected by the decrease in injection water mobility through polymer flooding?','a:4:{i:0;s:21:"Relative permeability";i:1;s:14:"Mobility ratio";i:2;s:13:"Rock porosity";i:3;s:18:"Capillary pressure";}','Mobility ratio','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000522','Manakah di antara berikut ini yang merupakan jenis polimer yang umum digunakan dalam aplikasi EOR?','multi','PFC000000009','Final Test','a:4:{i:0;s:4:"HPAM";i:1;s:7:"Xanthan";i:2;s:12:"Asam klorida";i:3;s:17:"Surfaktan anionik";}','','a:2:{i:0;s:4:"HPAM";i:1;s:7:"Xanthan";}','Which of the following are types of polymers commonly used in EOR applications?','a:4:{i:0;s:4:"HPAM";i:1;s:7:"Xanthan";i:2;s:17:"Hydrochloric acid";i:3;s:18:"Anionic surfactant";}','a:2:{i:0;s:4:"HPAM";i:1;s:7:"Xanthan";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000523','Apa kelemahan utama penggunaan HPAM (Hydrolyzed Polyacrylamide) pada kondisi reservoir dengan salinitas tinggi?','option','PFC000000009','Final Test','a:4:{i:0;s:35:"Sensitif terhadap degradasi mekanis";i:1;s:72:"Sensitif terhadap salinitas tinggi yang menyebabkan penurunan viskositas";i:2;s:38:"Sangat mahal dibandingkan polimer lain";i:3;s:26:"Tidak bisa larut dalam air";}','','Sensitif terhadap salinitas tinggi yang menyebabkan penurunan viskositas','What is the main disadvantage of using HPAM (Hydrolyzed Polyacrylamide) in high salinity reservoir conditions?','a:4:{i:0;s:35:"Sensitive to mechanical degradation";i:1;s:49:"Sensitive to high salinity causing viscosity loss";i:2;s:41:"Very expensive compared to other polymers";i:3;s:17:"Not water soluble";}','Sensitive to high salinity causing viscosity loss','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000524','Bagaimana pengaruh peningkatan viskositas air terhadap perolehan minyak (sweep efficiency)?','option','PFC000000009','Final Test','a:4:{i:0;s:51:"Meningkatkan efisiensi penyapuan (sweep efficiency)";i:1;s:30:"Menurunkan efisiensi penyapuan";i:2;s:23:"Tidak memiliki pengaruh";i:3;s:33:"Menyebabkan fingering lebih cepat";}','','Meningkatkan efisiensi penyapuan (sweep efficiency)','How does increasing water viscosity affect oil recovery (sweep efficiency)?','a:4:{i:0;s:26:"Increases sweep efficiency";i:1;s:26:"Decreases sweep efficiency";i:2;s:13:"Has no effect";i:3;s:23:"Causes faster fingering";}','Increases sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000525','Apa karakteristik utama dari biopolimer Xanthan dibandingkan dengan HPAM?','option','PFC000000009','Final Test','a:4:{i:0;s:37:"Lebih tahan terhadap salinitas tinggi";i:1;s:20:"Lebih murah harganya";i:2;s:38:"Lebih rentan terhadap degradasi termal";i:3;s:39:"Memiliki struktur linear yang sederhana";}','','Lebih tahan terhadap salinitas tinggi','What is the main characteristic of the biopolymer Xanthan compared to HPAM?','a:4:{i:0;s:31:"More resistant to high salinity";i:1;s:16:"Cheaper in price";i:2;s:39:"More susceptible to thermal degradation";i:3;s:29:"Has a simple linear structure";}','More resistant to high salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000526','Mengapa mobility ratio yang lebih kecil dari 1 (M < 1) diinginkan dalam proses injeksi polimer?','option','PFC000000009','Final Test','a:4:{i:0;s:32:"Untuk mencegah viscous fingering";i:1;s:49:"Untuk meningkatkan tekanan injeksi secara ekstrem";i:2;s:42:"Untuk mengurangi saturasi air irreduksibel";i:3;s:29:"Untuk mempercepat laju korosi";}','','Untuk mencegah viscous fingering','Why is a mobility ratio of less than 1 (M < 1) desirable in polymer injection processes?','a:4:{i:0;s:28:"To prevent viscous fingering";i:1;s:42:"To increase injection pressure excessively";i:2;s:38:"To reduce irreducible water saturation";i:3;s:28:"To accelerate corrosion rate";}','To prevent viscous fingering','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000527','Faktor apa saja yang membatasi efektivitas injeksi polimer di lapangan?','multi','PFC000000009','Final Test','a:4:{i:0;s:16:"Degradasi termal";i:1;s:28:"Adsorpsi polimer pada batuan";i:2;s:37:"Viskositas fluida yang terlalu rendah";i:3;s:17:"Salinitas formasi";}','','a:3:{i:0;s:16:"Degradasi termal";i:1;s:28:"Adsorpsi polimer pada batuan";i:2;s:17:"Salinitas formasi";}','What factors limit the effectiveness of polymer injection in the field?','a:4:{i:0;s:19:"Thermal degradation";i:1;s:26:"Polymer adsorption on rock";i:2;s:31:"Fluid viscosity that is too low";i:3;s:18:"Formation salinity";}','a:3:{i:0;s:19:"Thermal degradation";i:1;s:26:"Polymer adsorption on rock";i:2;s:18:"Formation salinity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000528','Pada kondisi reservoir apa injeksi polimer biasanya paling efektif diterapkan?','option','PFC000000009','Final Test','a:4:{i:0;s:37:"Reservoir dengan permeabilitas rendah";i:1;s:37:"Reservoir dengan heterogenitas tinggi";i:2;s:35:"Reservoir dengan suhu di atas 150 C";i:3;s:51:"Reservoir dengan saturasi minyak sisa sangat rendah";}','','Reservoir dengan heterogenitas tinggi','In what reservoir conditions is polymer injection usually most effectively applied?','a:4:{i:0;s:27:"Low permeability reservoirs";i:1;s:29:"High heterogeneity reservoirs";i:2;s:40:"Reservoirs with temperatures above 150 C";i:3;s:48:"Reservoirs with very low residual oil saturation";}','High heterogeneity reservoirs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000529','Apa istilah untuk fenomena kehilangan polimer ke dalam matriks batuan selama injeksi?','option','PFC000000009','Final Test','a:4:{i:0;s:8:"Adsorpsi";i:1;s:5:"Erosi";i:2;s:10:"Infiltrasi";i:3;s:9:"Evaporasi";}','','Adsorpsi','What is the term for the phenomenon of polymer loss into the rock matrix during injection?','a:4:{i:0;s:10:"Adsorption";i:1;s:7:"Erosion";i:2;s:12:"Infiltration";i:3;s:11:"Evaporation";}','Adsorption','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000530','Dalam desain slug polimer, apa yang dimaksud dengan tapering?','option','PFC000000009','Final Test','a:4:{i:0;s:47:"Pengurangan konsentrasi polimer secara bertahap";i:1;s:34:"Peningkatan tekanan secara drastis";i:2;s:28:"Pencampuran dengan surfaktan";i:3;s:24:"Pembersihan lubang sumur";}','','Pengurangan konsentrasi polimer secara bertahap','In polymer slug design, what is meant by tapering?','a:4:{i:0;s:42:"Gradual reduction of polymer concentration";i:1;s:25:"Drastic pressure increase";i:2;s:22:"Mixing with surfactant";i:3;s:17:"Wellbore cleaning";}','Gradual reduction of polymer concentration','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000531','Apa dampak negatif dari degradasi mekanis (shear degradation) pada polimer HPAM?','option','PFC000000009','Final Test','a:4:{i:0;s:49:"Penurunan berat molekul dan kehilangan viskositas";i:1;s:37:"Peningkatan viskositas secara drastis";i:2;s:37:"Penyumbatan total pada zona produktif";i:3;s:29:"Pembentukan emulsi minyak-air";}','','Penurunan berat molekul dan kehilangan viskositas','What is the negative impact of shear degradation on HPAM polymer?','a:4:{i:0;s:51:"Reduction in molecular weight and loss of viscosity";i:1;s:29:"Drastic increase in viscosity";i:2;s:34:"Total plugging of productive zones";i:3;s:32:"Formation of oil-water emulsions";}','Reduction in molecular weight and loss of viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000532','Manakah pernyataan yang benar mengenai mobilitas fluida (lambda)?','option','PFC000000009','Final Test','a:4:{i:0;s:48:"Berbanding terbalik dengan permeabilitas relatif";i:1;s:41:"Berbanding lurus dengan viskositas fluida";i:2;s:44:"Berbanding terbalik dengan viskositas fluida";i:3;s:29:"Tidak bergantung pada tekanan";}','','Berbanding terbalik dengan viskositas fluida','Which statement is correct regarding fluid mobility (lambda)?','a:4:{i:0;s:47:"Inversely proportional to relative permeability";i:1;s:40:"Directly proportional to fluid viscosity";i:2;s:41:"Inversely proportional to fluid viscosity";i:3;s:27:"Does not depend on pressure";}','Inversely proportional to fluid viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000533','Mengapa injeksi polimer lebih unggul daripada waterflooding konvensional dalam hal perolehan minyak?','option','PFC000000009','Final Test','a:4:{i:0;s:47:"Memperbaiki vertical dan areal sweep efficiency";i:1;s:45:"Mengurangi biaya infrastruktur secara drastis";i:2;s:53:"Menghilangkan kebutuhan akan fasilitas pengolahan air";i:3;s:43:"Secara langsung melarutkan deposit paraffin";}','','Memperbaiki vertical dan areal sweep efficiency','Why is polymer injection superior to conventional waterflooding in terms of oil recovery?','a:4:{i:0;s:44:"Improves vertical and areal sweep efficiency";i:1;s:40:"Drastically reduces infrastructure costs";i:2;s:50:"Eliminates the need for water treatment facilities";i:3;s:36:"Directly dissolves paraffin deposits";}','Improves vertical and areal sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000534','Apa tujuan utama dari proses pre-flush dalam desain Chemical EOR?','option','PFC000000009','Final Test','a:4:{i:0;s:50:"Menyesuaikan salinitas dan pH lingkungan reservoir";i:1;s:27:"Meningkatkan suhu reservoir";i:2;s:26:"Menambah viskositas minyak";i:3;s:43:"Membersihkan sisa bor di dekat lubang sumur";}','','Menyesuaikan salinitas dan pH lingkungan reservoir','What is the main purpose of pre-flush in Chemical EOR design?','a:4:{i:0;s:54:"Adjusting salinity and pH of the reservoir environment";i:1;s:32:"Increasing reservoir temperature";i:2;s:24:"Increasing oil viscosity";i:3;s:43:"Cleaning drilling residue near the wellbore";}','Adjusting salinity and pH of the reservoir environment','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000535','Bagaimana pengaruh suhu reservoir yang sangat tinggi terhadap stabilitas kimiawi HPAM?','option','PFC000000009','Final Test','a:4:{i:0;s:44:"Mempercepat hidrolisis dan degradasi polimer";i:1;s:32:"Meningkatkan efektivitas polimer";i:2;s:29:"Tidak berpengaruh sama sekali";i:3;s:37:"Mengubah polimer menjadi bentuk padat";}','','Mempercepat hidrolisis dan degradasi polimer','How does very high reservoir temperature affect the chemical stability of HPAM?','a:4:{i:0;s:46:"Accelerates hydrolysis and polymer degradation";i:1;s:31:"Increases polymer effectiveness";i:2;s:20:"Has no effect at all";i:3;s:32:"Converts polymer into solid form";}','Accelerates hydrolysis and polymer degradation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000536','Dalam konteks polimer flooding, apa yang dimaksud dengan ''resistance factor''?','option','PFC000000009','Final Test','a:4:{i:0;s:54:"Rasio mobilitas air terhadap mobilitas larutan polimer";i:1;s:48:"Rasio viskositas polimer terhadap viskositas air";i:2;s:54:"Rasio permeabilitas batuan setelah dan sebelum injeksi";i:3;s:24:"Faktor biaya operasional";}','','Rasio mobilitas air terhadap mobilitas larutan polimer','In the context of polymer flooding, what is meant by ''resistance factor''?','a:4:{i:0;s:52:"Ratio of water mobility to polymer solution mobility";i:1;s:45:"Ratio of polymer viscosity to water viscosity";i:2;s:53:"Ratio of rock permeability after and before injection";i:3;s:23:"Operational cost factor";}','Ratio of water mobility to polymer solution mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000537','Manakah yang benar tentang karakteristik Xanthan Gum?','multi','PFC000000009','Final Test','a:4:{i:0;s:20:"Merupakan biopolimer";i:1;s:24:"Tahan terhadap salinitas";i:2;s:42:"Sangat sensitif terhadap degradasi bakteri";i:3;s:33:"Sintetis dari turunan minyak bumi";}','','a:3:{i:0;s:20:"Merupakan biopolimer";i:1;s:24:"Tahan terhadap salinitas";i:2;s:42:"Sangat sensitif terhadap degradasi bakteri";}','Which of the following are true about the characteristics of Xanthan Gum?','a:4:{i:0;s:18:"It is a biopolymer";i:1;s:21:"Resistant to salinity";i:2;s:39:"Very sensitive to bacterial degradation";i:3;s:36:"Synthetic from petroleum derivatives";}','a:3:{i:0;s:18:"It is a biopolymer";i:1;s:21:"Resistant to salinity";i:2;s:39:"Very sensitive to bacterial degradation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000538','Apa tantangan utama dalam implementasi lapangan injeksi polimer yang berkaitan dengan sumur injeksi?','option','PFC000000009','Final Test','a:4:{i:0;s:44:"Penyumbatan formasi akibat viskositas tinggi";i:1;s:37:"Kerusakan pompa injeksi akibat korosi";i:2;s:31:"Penguapan polimer di dalam pipa";i:3;s:33:"Kesulitan dalam memonitor tekanan";}','','Penyumbatan formasi akibat viskositas tinggi','What is the main challenge in field implementation of polymer injection related to injection wells?','a:4:{i:0;s:40:"Formation plugging due to high viscosity";i:1;s:38:"Injection pump damage due to corrosion";i:2;s:32:"Polymer evaporation inside pipes";i:3;s:33:"Difficulty in monitoring pressure";}','Formation plugging due to high viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000539','Apa keuntungan menggunakan polimer dibandingkan dengan waterflooding saja pada reservoir heterogen?','option','PFC000000009','Final Test','a:4:{i:0;s:72:"Mengurangi aliran melalui zona dengan permeabilitas tinggi (thief zones)";i:1;s:34:"Meningkatkan permeabilitas absolut";i:2;s:50:"Menggantikan seluruh volume minyak dalam reservoir";i:3;s:30:"Menurunkan harga minyak mentah";}','','Mengurangi aliran melalui zona dengan permeabilitas tinggi (thief zones)','What is the advantage of using polymer compared to waterflooding alone in heterogeneous reservoirs?','a:4:{i:0;s:58:"Reduces flow through high permeability zones (thief zones)";i:1;s:31:"Increases absolute permeability";i:2;s:47:"Replaces the entire oil volume in the reservoir";i:3;s:23:"Lowers crude oil prices";}','Reduces flow through high permeability zones (thief zones)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000540','Apa fungsi utama dari penambahan surfaktan dalam metode Chemical EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:27:"Meningkatkan viskositas air";i:1;s:35:"Menurunkan tegangan antarmuka (IFT)";i:2;s:25:"Menambah porositas batuan";i:3;s:28:"Meningkatkan tekanan injeksi";}','','Menurunkan tegangan antarmuka (IFT)','What is the primary function of adding surfactants in Chemical EOR methods?','a:4:{i:0;s:24:"Increase water viscosity";i:1;s:32:"Reduce interfacial tension (IFT)";i:2;s:22:"Increase rock porosity";i:3;s:27:"Increase injection pressure";}','Reduce interfacial tension (IFT)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000541','Manakah mekanisme berikut yang terjadi saat alkaline diinjeksikan ke dalam reservoir?','multi','PFC000000010','Final Test','a:4:{i:0;s:28:"Perubahan wettability batuan";i:1;s:29:"Pembentukan surfaktan in-situ";i:2;s:27:"Peningkatan saturasi minyak";i:3;s:24:"Penurunan pH air formasi";}','','a:2:{i:0;s:28:"Perubahan wettability batuan";i:1;s:29:"Pembentukan surfaktan in-situ";}','Which of the following mechanisms occur when alkaline is injected into a reservoir?','a:4:{i:0;s:27:"Rock wettability alteration";i:1;s:29:"In-situ surfactant generation";i:2;s:26:"Increase in oil saturation";i:3;s:30:"Decrease in formation water pH";}','a:2:{i:0;s:27:"Rock wettability alteration";i:1;s:29:"In-situ surfactant generation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000542','Apa yang dimaksud dengan proses solubilisasi dalam konteks surfaktan?','option','PFC000000010','Final Test','a:4:{i:0;s:30:"Pembentukan emulsi makroskopis";i:1;s:42:"Pengikatan minyak ke dalam misel surfaktan";i:2;s:27:"Penguapan minyak oleh panas";i:3;s:27:"Pencucian garam dari batuan";}','','Pengikatan minyak ke dalam misel surfaktan','What is meant by the solubilization process in the context of surfactants?','a:4:{i:0;s:34:"Formation of macroscopic emulsions";i:1;s:45:"Incorporation of oil into surfactant micelles";i:2;s:26:"Evaporation of oil by heat";i:3;s:27:"Washing of salts from rocks";}','Incorporation of oil into surfactant micelles','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000543','Apa kepanjangan dari ASP dalam formulasi Chemical EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:27:"Alkaline Surfactant Polymer";i:1;s:24:"Active Solution Pressure";i:2;s:27:"Advanced Surfactant Process";i:3;s:22:"Acidic Solvent Process";}','','Alkaline Surfactant Polymer','What does ASP stand for in Chemical EOR formulations?','a:4:{i:0;s:27:"Alkaline Surfactant Polymer";i:1;s:24:"Active Solution Pressure";i:2;s:27:"Advanced Surfactant Process";i:3;s:22:"Acidic Solvent Process";}','Alkaline Surfactant Polymer','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000544','Mengapa perubahan wettability batuan dari oil-wet menjadi water-wet sangat penting dalam EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:29:"Untuk memperbesar ukuran pori";i:1;s:54:"Untuk melepas minyak yang terjebak di permukaan batuan";i:2;s:47:"Untuk menurunkan tekanan kapiler secara drastis";i:3;s:31:"Untuk meningkatkan densitas air";}','','Untuk melepas minyak yang terjebak di permukaan batuan','Why is the change of rock wettability from oil-wet to water-wet important in EOR?','a:4:{i:0;s:21:"To increase pore size";i:1;s:42:"To release oil trapped on the rock surface";i:2;s:40:"To drastically reduce capillary pressure";i:3;s:25:"To increase water density";}','To release oil trapped on the rock surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000545','Apa dampak negatif utama dari adsorpsi surfaktan pada matriks batuan?','option','PFC000000010','Final Test','a:4:{i:0;s:38:"Kehilangan konsentrasi surfaktan aktif";i:1;s:33:"Peningkatan permeabilitas absolut";i:2;s:28:"Penurunan pH larutan injeksi";i:3;s:30:"Peningkatan tegangan antarmuka";}','','Kehilangan konsentrasi surfaktan aktif','What is the main negative impact of surfactant adsorption on the rock matrix?','a:4:{i:0;s:39:"Loss of active surfactant concentration";i:1;s:33:"Increase in absolute permeability";i:2;s:33:"Decrease in injection solution pH";i:3;s:31:"Increase in interfacial tension";}','Loss of active surfactant concentration','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000546','Faktor apa yang paling mempengaruhi efisiensi surfaktan dalam menurunkan IFT?','option','PFC000000010','Final Test','a:4:{i:0;s:17:"Salinitas formasi";i:1;s:17:"Viskositas minyak";i:2;s:16:"Porositas batuan";i:3;s:19:"Kedalaman reservoir";}','','Salinitas formasi','Which factor most influences surfactant efficiency in reducing IFT?','a:4:{i:0;s:18:"Formation salinity";i:1;s:13:"Oil viscosity";i:2;s:13:"Rock porosity";i:3;s:15:"Reservoir depth";}','Formation salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000547','Dalam formulasi ASP, apa peran utama dari polimer?','option','PFC000000010','Final Test','a:4:{i:0;s:29:"Menurunkan tegangan antarmuka";i:1;s:27:"Mengontrol mobilitas fluida";i:2;s:15:"Meningkatkan pH";i:3;s:20:"Mengubah wettability";}','','Mengontrol mobilitas fluida','In an ASP formulation, what is the primary role of the polymer?','a:4:{i:0;s:26:"Reduce interfacial tension";i:1;s:22:"Control fluid mobility";i:2;s:11:"Increase pH";i:3;s:18:"Change wettability";}','Control fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000548','Apa yang terjadi pada sistem surfaktan jika suhu reservoir terlalu tinggi?','option','PFC000000010','Final Test','a:4:{i:0;s:25:"Degradasi kimia surfaktan";i:1;s:35:"Peningkatan kelarutan secara instan";i:2;s:18:"Penurunan adsorpsi";i:3;s:36:"Peningkatan efisiensi secara drastis";}','','Degradasi kimia surfaktan','What happens to the surfactant system if the reservoir temperature is too high?','a:4:{i:0;s:38:"Chemical degradation of the surfactant";i:1;s:30:"Instant increase in solubility";i:2;s:22:"Decrease in adsorption";i:3;s:30:"Drastic increase in efficiency";}','Chemical degradation of the surfactant','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000549','Kondisi reservoir mana yang paling tidak cocok untuk aplikasi alkaline flooding?','option','PFC000000010','Final Test','a:4:{i:0;s:34:"Reservoir minyak asam (acidic oil)";i:1;s:48:"Batuan karbonat dengan kandungan anhidrit tinggi";i:2;s:37:"Reservoir dengan permeabilitas tinggi";i:3;s:46:"Reservoir dengan saturasi minyak residu tinggi";}','','Batuan karbonat dengan kandungan anhidrit tinggi','Which reservoir condition is least suitable for alkaline flooding applications?','a:4:{i:0;s:21:"Acidic oil reservoirs";i:1;s:43:"Carbonate rocks with high anhydrite content";i:2;s:28:"High permeability reservoirs";i:3;s:44:"Reservoirs with high residual oil saturation";}','Carbonate rocks with high anhydrite content','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000550','Pilih dua keuntungan utama dari penggunaan Alkaline-Surfactant (AS) flooding dibandingkan surfaktan saja:','multi','PFC000000010','Final Test','a:4:{i:0;s:28:"Biaya kimia yang lebih murah";i:1;s:37:"Sinergi penurunan IFT yang lebih baik";i:2;s:42:"Pengurangan adsorpsi surfaktan pada batuan";i:3;s:41:"Peningkatan viskositas air secara spontan";}','','a:2:{i:0;s:28:"Biaya kimia yang lebih murah";i:1;s:42:"Pengurangan adsorpsi surfaktan pada batuan";}','Choose two main advantages of using Alkaline-Surfactant (AS) flooding compared to surfactants alone:','a:4:{i:0;s:22:"Cheaper chemical costs";i:1;s:28:"Better IFT reduction synergy";i:2;s:43:"Reduction of surfactant adsorption on rocks";i:3;s:36:"Spontaneous water viscosity increase";}','a:2:{i:0;s:22:"Cheaper chemical costs";i:1;s:43:"Reduction of surfactant adsorption on rocks";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000551','Apa tujuan dari tahap pre-flush dalam proyek Chemical EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:25:"Menyesuaikan pH reservoir";i:1;s:57:"Mengurangi salinitas untuk mencegah presipitasi surfaktan";i:2;s:27:"Meningkatkan suhu reservoir";i:3;s:35:"Membersihkan debris dari lubang bor";}','','Mengurangi salinitas untuk mencegah presipitasi surfaktan','What is the purpose of the pre-flush stage in a Chemical EOR project?','a:4:{i:0;s:19:"Adjust reservoir pH";i:1;s:51:"Reduce salinity to prevent surfactant precipitation";i:2;s:30:"Increase reservoir temperature";i:3;s:30:"Clean debris from the wellbore";}','Reduce salinity to prevent surfactant precipitation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000552','Bagaimana pengaruh tegangan antarmuka (IFT) terhadap recovery factor minyak?','option','PFC000000010','Final Test','a:4:{i:0;s:42:"Semakin tinggi IFT, semakin besar recovery";i:1;s:42:"Semakin rendah IFT, semakin besar recovery";i:2;s:42:"Tidak ada korelasi antara IFT dan recovery";i:3;s:44:"IFT hanya berpengaruh pada viskositas minyak";}','','Semakin rendah IFT, semakin besar recovery','How does interfacial tension (IFT) affect the oil recovery factor?','a:4:{i:0;s:38:"Higher IFT results in greater recovery";i:1;s:37:"Lower IFT results in greater recovery";i:2;s:48:"There is no correlation between IFT and recovery";i:3;s:30:"IFT only affects oil viscosity";}','Lower IFT results in greater recovery','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000553','Apa yang dimaksud dengan kondisi ''ultra-low IFT'' dalam Chemical EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:26:"IFT di bawah 10^-3 dyne/cm";i:1;s:22:"IFT di atas 10 dyne/cm";i:2;s:25:"IFT sama dengan air murni";i:3;s:17:"IFT tidak terukur";}','','IFT di bawah 10^-3 dyne/cm','What is meant by ''ultra-low IFT'' conditions in Chemical EOR?','a:4:{i:0;s:23:"IFT below 10^-3 dyne/cm";i:1;s:20:"IFT above 10 dyne/cm";i:2;s:23:"IFT equal to pure water";i:3;s:19:"IFT is immeasurable";}','IFT below 10^-3 dyne/cm','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000554','Mengapa pH tinggi pada alkaline flooding dapat menyebabkan masalah kerak (scaling)?','option','PFC000000010','Final Test','a:4:{i:0;s:54:"Reaksi antara alkali dengan ion kalsium di air formasi";i:1;s:30:"Polimer bereaksi dengan batuan";i:2;s:17:"Surfaktan membeku";i:3;s:27:"Perubahan tekanan reservoir";}','','Reaksi antara alkali dengan ion kalsium di air formasi','Why can high pH in alkaline flooding cause scaling problems?','a:4:{i:0;s:59:"Reaction between alkali and calcium ions in formation water";i:1;s:28:"Polymer reacts with the rock";i:2;s:18:"Surfactant freezes";i:3;s:29:"Changes in reservoir pressure";}','Reaction between alkali and calcium ions in formation water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000555','Apa parameter utama yang diamati saat melakukan uji laboratorium ''bottle test'' untuk surfaktan?','option','PFC000000010','Final Test','a:4:{i:0;s:44:"Waktu pemisahan fase dan kejelasan antarmuka";i:1;s:16:"Kekerasan batuan";i:2;s:13:"Laju alir gas";i:3;s:22:"Tekanan kapiler batuan";}','','Waktu pemisahan fase dan kejelasan antarmuka','What is the main parameter observed during ''bottle test'' laboratory trials for surfactants?','a:4:{i:0;s:43:"Phase separation time and interface clarity";i:1;s:13:"Rock hardness";i:2;s:13:"Gas flow rate";i:3;s:23:"Rock capillary pressure";}','Phase separation time and interface clarity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000556','Faktor apa yang menentukan pemilihan jenis surfaktan untuk reservoir tertentu?','multi','PFC000000010','Final Test','a:4:{i:0;s:20:"Temperatur reservoir";i:1;s:31:"Kandungan salinitas air formasi";i:2;s:22:"Jenis batuan reservoir";i:3;s:25:"Harga pasar minyak mentah";}','','a:3:{i:0;s:20:"Temperatur reservoir";i:1;s:31:"Kandungan salinitas air formasi";i:2;s:22:"Jenis batuan reservoir";}','What factors determine the selection of surfactant type for a specific reservoir?','a:4:{i:0;s:21:"Reservoir temperature";i:1;s:32:"Formation water salinity content";i:2;s:19:"Reservoir rock type";i:3;s:22:"Crude oil market price";}','a:3:{i:0;s:21:"Reservoir temperature";i:1;s:32:"Formation water salinity content";i:2;s:19:"Reservoir rock type";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000557','Apa efek utama dari penambahan alkali pada minyak mentah yang mengandung asam naphthenic?','option','PFC000000010','Final Test','a:4:{i:0;s:32:"Pembentukan sabun (soap) in-situ";i:1;s:41:"Penurunan viskositas minyak secara termal";i:2;s:25:"Peningkatan kejenuhan air";i:3;s:21:"Pembentukan gas alami";}','','Pembentukan sabun (soap) in-situ','What is the primary effect of adding alkali to crude oil containing naphthenic acids?','a:4:{i:0;s:22:"In-situ soap formation";i:1;s:34:"Thermal reduction of oil viscosity";i:2;s:28:"Increase in water saturation";i:3;s:24:"Formation of natural gas";}','In-situ soap formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000558','Manakah dari berikut ini yang merupakan kelemahan utama dari chemical flooding?','option','PFC000000010','Final Test','a:4:{i:0;s:29:"Biaya bahan kimia yang tinggi";i:1;s:34:"Produksi minyak yang terlalu cepat";i:2;s:49:"Kebutuhan akan tekanan injeksi yang sangat rendah";i:3;s:48:"Sifatnya yang tidak ramah lingkungan sama sekali";}','','Biaya bahan kimia yang tinggi','Which of the following is a major disadvantage of chemical flooding?','a:4:{i:0;s:22:"High cost of chemicals";i:1;s:31:"Oil production that is too fast";i:2;s:43:"Requirement for very low injection pressure";i:3;s:55:"Its nature which is not environmentally friendly at all";}','High cost of chemicals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000559','Pada grafik ternary phase diagram untuk sistem surfaktan, area apa yang menunjukkan pembentukan mikroemulsi optimum?','option','PFC000000010','Final Test','a:4:{i:0;s:27:"Area tiga fase (Winsor III)";i:1;s:21:"Area air-dalam-minyak";i:2;s:21:"Area minyak-dalam-air";i:3;s:31:"Area di luar batas solubilisasi";}','','Area tiga fase (Winsor III)','On a ternary phase diagram for surfactant systems, which area indicates the formation of optimum microemulsion?','a:4:{i:0;s:29:"Three-phase area (Winsor III)";i:1;s:17:"Water-in-oil area";i:2;s:17:"Oil-in-water area";i:3;s:40:"Area outside the solubilization boundary";}','Three-phase area (Winsor III)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000560','Apa mekanisme utama penurunan viskositas minyak pada metode steamflooding?','option','PFC000000011','Final Test','a:4:{i:0;s:16:"Pemanasan termal";i:1;s:12:"Ekspansi gas";i:2;s:24:"Pengurangan saturasi air";i:3;s:29:"Peningkatan tekanan reservoir";}','','Pemanasan termal','What is the primary mechanism for oil viscosity reduction in steamflooding?','a:4:{i:0;s:15:"Thermal heating";i:1;s:13:"Gas expansion";i:2;s:26:"Water saturation reduction";i:3;s:30:"Increase in reservoir pressure";}','Thermal heating','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000561','Manakah dari berikut ini yang merupakan karakteristik utama dari proses SAGD?','multi','PFC000000011','Final Test','a:4:{i:0;s:36:"Penggunaan sumur horizontal pasangan";i:1;s:33:"Gravitasi sebagai pendorong utama";i:2;s:15:"Injeksi gas CO2";i:3;s:23:"Pemanasan terus-menerus";}','','a:3:{i:0;s:36:"Penggunaan sumur horizontal pasangan";i:1;s:33:"Gravitasi sebagai pendorong utama";i:2;s:23:"Pemanasan terus-menerus";}','Which of the following are key characteristics of the SAGD process?','a:4:{i:0;s:30:"Use of paired horizontal wells";i:1;s:29:"Gravity as the primary driver";i:2;s:17:"CO2 gas injection";i:3;s:18:"Continuous heating";}','a:3:{i:0;s:30:"Use of paired horizontal wells";i:1;s:29:"Gravity as the primary driver";i:2;s:18:"Continuous heating";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000562','Metode cyclic steam stimulation (CSS) sering disebut juga dengan istilah?','option','PFC000000011','Final Test','a:4:{i:0;s:13:"Huff and puff";i:1;s:11:"Steam drive";i:2;s:16:"Combustion front";i:3;s:13:"Gas cap drive";}','','Huff and puff','The cyclic steam stimulation (CSS) method is also known as?','a:4:{i:0;s:13:"Huff and puff";i:1;s:11:"Steam drive";i:2;s:16:"Combustion front";i:3;s:13:"Gas cap drive";}','Huff and puff','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000563','Pada in-situ combustion, zona apa yang terletak tepat di belakang zona pembakaran?','option','PFC000000011','Final Test','a:4:{i:0;s:27:"Zona terbakar (burned zone)";i:1;s:22:"Zona kokas (coke zone)";i:2;s:21:"Zona uap (steam zone)";i:3;s:18:"Zona minyak dingin";}','','Zona kokas (coke zone)','In in-situ combustion, which zone is located immediately behind the combustion front?','a:4:{i:0;s:11:"Burned zone";i:1;s:9:"Coke zone";i:2;s:10:"Steam zone";i:3;s:13:"Cold oil zone";}','Coke zone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000564','Manakah gas yang paling umum digunakan dalam miscible gas injection untuk meningkatkan perolehan minyak?','option','PFC000000011','Final Test','a:4:{i:0;s:3:"CO2";i:1;s:8:"Nitrogen";i:2;s:5:"Udara";i:3;s:7:"Oksigen";}','','CO2','Which gas is most commonly used in miscible gas injection to enhance oil recovery?','a:4:{i:0;s:3:"CO2";i:1;s:8:"Nitrogen";i:2;s:3:"Air";i:3;s:6:"Oxygen";}','CO2','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000565','Apa tujuan utama dari teknik WAG (Water-Alternating-Gas) dalam injeksi gas?','option','PFC000000011','Final Test','a:4:{i:0;s:24:"Mengontrol mobilitas gas";i:1;s:28:"Menambah tekanan hidrostatik";i:2;s:25:"Mengurangi viskositas air";i:3;s:20:"Mencegah korosi pipa";}','','Mengontrol mobilitas gas','What is the primary purpose of the WAG (Water-Alternating-Gas) technique in gas injection?','a:4:{i:0;s:20:"Gas mobility control";i:1;s:29:"Increase hydrostatic pressure";i:2;s:22:"Reduce water viscosity";i:3;s:22:"Prevent pipe corrosion";}','Gas mobility control','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000566','Faktor apa yang paling membatasi penerapan in-situ combustion di lapangan?','option','PFC000000011','Final Test','a:4:{i:0;s:42:"Kompleksitas operasional dan kontrol front";i:1;s:16:"Ketersediaan air";i:2;s:19:"Biaya material baja";i:3;s:32:"Kedalaman reservoir yang dangkal";}','','Kompleksitas operasional dan kontrol front','What is the most limiting factor for the application of in-situ combustion in the field?','a:4:{i:0;s:40:"Operational complexity and front control";i:1;s:18:"Water availability";i:2;s:19:"Steel material cost";i:3;s:23:"Shallow reservoir depth";}','Operational complexity and front control','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000567','Metode thermal mana yang paling efektif untuk reservoir minyak berat yang sangat kental dan tebal?','option','PFC000000011','Final Test','a:4:{i:0;s:4:"SAGD";i:1;s:13:"Gas injection";i:2;s:13:"Waterflooding";i:3;s:17:"Chemical flooding";}','','SAGD','Which thermal method is most effective for thick, highly viscous heavy oil reservoirs?','a:4:{i:0;s:4:"SAGD";i:1;s:13:"Gas injection";i:2;s:13:"Waterflooding";i:3;s:17:"Chemical flooding";}','SAGD','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000568','Dalam injeksi CO2 misibel, mekanisme utama peningkatan recovery adalah?','multi','PFC000000011','Final Test','a:4:{i:0;s:15:"Swelling minyak";i:1;s:22:"Pengurangan viskositas";i:2;s:25:"Ekstraksi komponen ringan";i:3;s:33:"Peningkatan permeabilitas absolut";}','','a:3:{i:0;s:15:"Swelling minyak";i:1;s:22:"Pengurangan viskositas";i:2;s:25:"Ekstraksi komponen ringan";}','In miscible CO2 injection, the primary recovery mechanisms are?','a:4:{i:0;s:12:"Oil swelling";i:1;s:19:"Viscosity reduction";i:2;s:30:"Extraction of light components";i:3;s:33:"Increase in absolute permeability";}','a:3:{i:0;s:12:"Oil swelling";i:1;s:19:"Viscosity reduction";i:2;s:30:"Extraction of light components";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000569','Apa yang dimaksud dengan Minimum Miscibility Pressure (MMP)?','option','PFC000000011','Final Test','a:4:{i:0;s:57:"Tekanan minimum agar gas bercampur sempurna dengan minyak";i:1;s:24:"Tekanan maksimum injeksi";i:2;s:21:"Tekanan pecah formasi";i:3;s:23:"Tekanan saturasi minyak";}','','Tekanan minimum agar gas bercampur sempurna dengan minyak','What is meant by Minimum Miscibility Pressure (MMP)?','a:4:{i:0;s:52:"Minimum pressure for gas to become miscible with oil";i:1;s:26:"Maximum injection pressure";i:2;s:28:"Formation breakdown pressure";i:3;s:23:"Oil saturation pressure";}','Minimum pressure for gas to become miscible with oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000570','Keuntungan utama menggunakan injeksi gas hidrokarbon dibandingkan CO2 adalah?','option','PFC000000011','Final Test','a:4:{i:0;s:58:"Ketersediaan dan biaya yang lebih murah di lokasi tertentu";i:1;s:36:"Tidak memerlukan fasilitas kompresor";i:2;s:20:"Lebih berat dari CO2";i:3;s:26:"Tidak bisa menjadi misibel";}','','Ketersediaan dan biaya yang lebih murah di lokasi tertentu','The main advantage of using hydrocarbon gas injection compared to CO2 is?','a:4:{i:0;s:48:"Availability and lower cost in certain locations";i:1;s:38:"Does not require compressor facilities";i:2;s:16:"Heavier than CO2";i:3;s:18:"Cannot be miscible";}','Availability and lower cost in certain locations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000571','Dalam steamflooding, kehilangan panas di dalam sumur dapat dikurangi dengan menggunakan?','option','PFC000000011','Final Test','a:4:{i:0;s:18:"Tubing berinsulasi";i:1;s:18:"Casing baja karbon";i:2;s:20:"Cementing yang tipis";i:3;s:18:"Injeksi air dingin";}','','Tubing berinsulasi','In steamflooding, heat loss inside the wellbore can be reduced by using?','a:4:{i:0;s:16:"Insulated tubing";i:1;s:19:"Carbon steel casing";i:2;s:14:"Thin cementing";i:3;s:20:"Cold water injection";}','Insulated tubing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000572','Manakah kriteria reservoir yang umum untuk metode thermal EOR?','multi','PFC000000011','Final Test','a:4:{i:0;s:31:"Minyak dengan viskositas tinggi";i:1;s:39:"Kedalaman reservoir tidak terlalu dalam";i:2;s:16:"Porositas tinggi";i:3;s:49:"Batuan reservoir dengan kandungan karbonat tinggi";}','','a:3:{i:0;s:31:"Minyak dengan viskositas tinggi";i:1;s:39:"Kedalaman reservoir tidak terlalu dalam";i:2;s:16:"Porositas tinggi";}','Which are the common reservoir criteria for thermal EOR methods?','a:4:{i:0;s:18:"High oil viscosity";i:1;s:23:"Shallow reservoir depth";i:2;s:13:"High porosity";i:3;s:37:"High carbonate content reservoir rock";}','a:3:{i:0;s:18:"High oil viscosity";i:1;s:23:"Shallow reservoir depth";i:2;s:13:"High porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000573','Fenomena ''gravity override'' pada injeksi gas disebabkan oleh?','option','PFC000000011','Final Test','a:4:{i:0;s:40:"Perbedaan densitas antara gas dan minyak";i:1;s:35:"Tekanan injeksi yang terlalu rendah";i:2;s:26:"Permeabilitas yang seragam";i:3;s:29:"Peningkatan viskositas minyak";}','','Perbedaan densitas antara gas dan minyak','The ''gravity override'' phenomenon in gas injection is caused by?','a:4:{i:0;s:38:"Density difference between gas and oil";i:1;s:34:"Injection pressure that is too low";i:2;s:20:"Uniform permeability";i:3;s:23:"Increased oil viscosity";}','Density difference between gas and oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000574','In-situ combustion dikategorikan sebagai metode thermal karena?','option','PFC000000011','Final Test','a:4:{i:0;s:37:"Menghasilkan panas di dalam reservoir";i:1;s:31:"Menggunakan boiler di permukaan";i:2;s:21:"Menginjeksi uap panas";i:3;s:27:"Menggunakan pemanas listrik";}','','Menghasilkan panas di dalam reservoir','In-situ combustion is categorized as a thermal method because?','a:4:{i:0;s:38:"It generates heat within the reservoir";i:1;s:30:"It uses boilers at the surface";i:2;s:20:"It injects hot steam";i:3;s:24:"It uses electric heaters";}','It generates heat within the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000575','Apa dampak negatif injeksi CO2 yang harus diwaspadai di dalam pipa produksi?','option','PFC000000011','Final Test','a:4:{i:0;s:39:"Korosi akibat pembentukan asam karbonat";i:1;s:29:"Peningkatan viskositas minyak";i:2;s:19:"Endapan lilin (wax)";i:3;s:31:"Penurunan permeabilitas absolut";}','','Korosi akibat pembentukan asam karbonat','What is a negative impact of CO2 injection that must be monitored in production tubing?','a:4:{i:0;s:40:"Corrosion due to carbonic acid formation";i:1;s:25:"Increase in oil viscosity";i:2;s:14:"Wax deposition";i:3;s:33:"Decrease in absolute permeability";}','Corrosion due to carbonic acid formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000576','Proses injeksi gas yang dilakukan dengan tekanan di atas MMP disebut?','option','PFC000000011','Final Test','a:4:{i:0;s:17:"Miscible flooding";i:1;s:19:"Immiscible flooding";i:2;s:13:"Waterflooding";i:3;s:12:"Cyclic steam";}','','Miscible flooding','A gas injection process carried out at a pressure above MMP is called?','a:4:{i:0;s:17:"Miscible flooding";i:1;s:19:"Immiscible flooding";i:2;s:13:"Waterflooding";i:3;s:12:"Cyclic steam";}','Miscible flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000577','Apa kelemahan utama dari metode Cyclic Steam Stimulation (CSS)?','option','PFC000000011','Final Test','a:4:{i:0;s:27:"Recovery factor yang rendah";i:1;s:35:"Hanya efisien untuk reservoir dalam";i:2;s:28:"Membutuhkan air yang sedikit";i:3;s:23:"Biaya operasional murah";}','','Recovery factor yang rendah','What is the main disadvantage of the Cyclic Steam Stimulation (CSS) method?','a:4:{i:0;s:19:"Low recovery factor";i:1;s:34:"Only efficient for deep reservoirs";i:2;s:21:"Requires little water";i:3;s:20:"Low operational cost";}','Low recovery factor','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000578','Dalam injeksi gas, apa fungsi dari ''slug'' gas?','option','PFC000000011','Final Test','a:4:{i:0;s:39:"Mendorong minyak ke arah sumur produksi";i:1;s:26:"Menambah viskositas minyak";i:2;s:28:"Mengurangi tekanan reservoir";i:3;s:23:"Menghentikan aliran air";}','','Mendorong minyak ke arah sumur produksi','In gas injection, what is the function of the gas ''slug''?','a:4:{i:0;s:39:"To push oil towards the production well";i:1;s:25:"To increase oil viscosity";i:2;s:28:"To reduce reservoir pressure";i:3;s:18:"To stop water flow";}','To push oil towards the production well','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000579','Parameter utama yang menentukan keberhasilan injeksi thermal adalah?','multi','PFC000000011','Final Test','a:4:{i:0;s:38:"Efisiensi penyapuan (sweep efficiency)";i:1;s:27:"Efisiensi perpindahan panas";i:2;s:32:"Kondisi keekonomian harga minyak";i:3;s:15:"Kedalaman sumur";}','','a:3:{i:0;s:38:"Efisiensi penyapuan (sweep efficiency)";i:1;s:27:"Efisiensi perpindahan panas";i:2;s:32:"Kondisi keekonomian harga minyak";}','The main parameters that determine the success of thermal injection are?','a:4:{i:0;s:16:"Sweep efficiency";i:1;s:24:"Heat transfer efficiency";i:2;s:32:"Economic conditions of oil price";i:3;s:10:"Well depth";}','a:3:{i:0;s:16:"Sweep efficiency";i:1;s:24:"Heat transfer efficiency";i:2;s:32:"Economic conditions of oil price";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000580','Apa tujuan utama dari pelaksanaan proyek pilot EOR sebelum penerapan skala penuh?','option','PFC000000012','Final Test','a:4:{i:0;s:55:"Mengurangi ketidakpastian teknis dan risiko operasional";i:1;s:48:"Meningkatkan harga minyak mentah secara langsung";i:2;s:41:"Mengurangi biaya eksplorasi di sumur baru";i:3;s:47:"Menghilangkan kebutuhan akan studi laboratorium";}','','Mengurangi ketidakpastian teknis dan risiko operasional','What is the primary objective of implementing an EOR pilot project before full-field application?','a:4:{i:0;s:52:"Reducing technical uncertainty and operational risks";i:1;s:36:"Directly increasing crude oil prices";i:2;s:39:"Reducing exploration costs in new wells";i:3;s:43:"Eliminating the need for laboratory studies";}','Reducing technical uncertainty and operational risks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000581','Parameter ekonomi mana yang paling umum digunakan untuk mengevaluasi profitabilitas proyek EOR?','multi','PFC000000012','Final Test','a:4:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";i:2;s:36:"Total biaya operasional tanpa diskon";i:3;s:26:"Kecepatan pengeboran sumur";}','','a:2:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";}','Which economic parameters are most commonly used to evaluate the profitability of EOR projects?','a:4:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";i:2;s:34:"Total undiscounted operating costs";i:3;s:19:"Well drilling speed";}','a:2:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000582','Faktor risiko teknis yang paling signifikan dalam penerapan injeksi polimer adalah?','option','PFC000000012','Final Test','a:4:{i:0;s:39:"Degradasi polimer akibat suhu reservoir";i:1;s:34:"Kurangnya ketersediaan air injeksi";i:2;s:23:"Kenaikan harga gas alam";i:3;s:33:"Peningkatan permeabilitas formasi";}','','Degradasi polimer akibat suhu reservoir','The most significant technical risk factor in polymer injection application is?','a:4:{i:0;s:48:"Polymer degradation due to reservoir temperature";i:1;s:36:"Lack of injection water availability";i:2;s:26:"Natural gas price increase";i:3;s:31:"Formation permeability increase";}','Polymer degradation due to reservoir temperature','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000583','Dalam konteks HSE, aspek apa yang menjadi perhatian utama pada injeksi CO2 EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:30:"Kebocoran gas CO2 ke permukaan";i:1;s:27:"Polusi suara dari kompresor";i:2;s:26:"Tingginya konsumsi listrik";i:3;s:24:"Karat pada pipa produksi";}','','Kebocoran gas CO2 ke permukaan','In the context of HSE, what is the primary concern during CO2 EOR injection?','a:4:{i:0;s:33:"Leakage of CO2 gas to the surface";i:1;s:32:"Noise pollution from compressors";i:2;s:28:"High electricity consumption";i:3;s:33:"Corrosion in production pipelines";}','Leakage of CO2 gas to the surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000584','Mengapa proyek EOR seringkali membutuhkan harga minyak yang tinggi untuk layak secara ekonomi?','option','PFC000000012','Final Test','a:4:{i:0;s:44:"Biaya bahan kimia dan operasional yang mahal";i:1;s:37:"Penurunan produksi yang terlalu cepat";i:2;s:35:"Kebutuhan akan alat pengeboran baru";i:3;s:34:"Pajak pemerintah yang lebih rendah";}','','Biaya bahan kimia dan operasional yang mahal','Why do EOR projects often require high oil prices to be economically viable?','a:4:{i:0;s:37:"High cost of chemicals and operations";i:1;s:35:"Excessively fast production decline";i:2;s:31:"Need for new drilling equipment";i:3;s:22:"Lower government taxes";}','High cost of chemicals and operations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000585','Apa yang dimaksud dengan ''screen analysis'' pada tahap perencanaan proyek EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:57:"Penyaringan reservoir berdasarkan kriteria kesesuaian EOR";i:1;s:33:"Pemilihan lokasi sumur pengeboran";i:2;s:41:"Pemeriksaan kesehatan pekerja di lapangan";i:3;s:29:"Penyaringan air untuk injeksi";}','','Penyaringan reservoir berdasarkan kriteria kesesuaian EOR','What is meant by ''screen analysis'' in the EOR project planning phase?','a:4:{i:0;s:57:"Screening of reservoirs based on EOR suitability criteria";i:1;s:36:"Selection of well drilling locations";i:2;s:30:"Checking field workers'' health";i:3;s:29:"Filtering water for injection";}','Screening of reservoirs based on EOR suitability criteria','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000586','Manakah pernyataan yang benar mengenai masa depan teknologi EOR?','multi','PFC000000012','Final Test','a:4:{i:0;s:46:"Integrasi dengan teknologi digitalisasi dan AI";i:1;s:42:"Fokus pada pengurangan emisi karbon (CCUS)";i:2;s:41:"Penghentian total penggunaan metode kimia";i:3;s:39:"Peningkatan efisiensi biaya operasional";}','','a:3:{i:0;s:46:"Integrasi dengan teknologi digitalisasi dan AI";i:1;s:42:"Fokus pada pengurangan emisi karbon (CCUS)";i:2;s:39:"Peningkatan efisiensi biaya operasional";}','Which statements are correct regarding the future of EOR technology?','a:4:{i:0;s:51:"Integration with digitalization and AI technologies";i:1;s:41:"Focus on carbon emission reduction (CCUS)";i:2;s:40:"Total cessation of chemical method usage";i:3;s:42:"Improvement of operational cost efficiency";}','a:3:{i:0;s:51:"Integration with digitalization and AI technologies";i:1;s:41:"Focus on carbon emission reduction (CCUS)";i:2;s:42:"Improvement of operational cost efficiency";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000587','Apa dampak negatif dari ''breakthrough'' fluida injeksi pada sumur produksi?','option','PFC000000012','Final Test','a:4:{i:0;s:45:"Penurunan efisiensi sapuan (sweep efficiency)";i:1;s:29:"Peningkatan tekanan reservoir";i:2;s:27:"Penurunan viskositas minyak";i:3;s:33:"Peningkatan permeabilitas relatif";}','','Penurunan efisiensi sapuan (sweep efficiency)','What is the negative impact of injection fluid ''breakthrough'' at the production well?','a:4:{i:0;s:29:"Reduction in sweep efficiency";i:1;s:30:"Increase in reservoir pressure";i:2;s:25:"Decrease in oil viscosity";i:3;s:33:"Increase in relative permeability";}','Reduction in sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000588','Dalam evaluasi ekonomi, apa arti dari Discounted Cash Flow (DCF)?','option','PFC000000012','Final Test','a:4:{i:0;s:51:"Nilai uang masa depan yang disesuaikan ke masa kini";i:1;s:40:"Total pendapatan sebelum dikurangi pajak";i:2;s:34:"Jumlah minyak yang akan diproduksi";i:3;s:23:"Biaya modal awal proyek";}','','Nilai uang masa depan yang disesuaikan ke masa kini','In economic evaluation, what is the meaning of Discounted Cash Flow (DCF)?','a:4:{i:0;s:45:"Future value of money adjusted to the present";i:1;s:26:"Total revenue before taxes";i:2;s:28:"Amount of oil to be produced";i:3;s:35:"Initial project capital expenditure";}','Future value of money adjusted to the present','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000589','Mengapa penentuan heterogenitas reservoir sangat krusial dalam perencanaan EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:52:"Karena mempengaruhi pola aliran dan efisiensi sapuan";i:1;s:47:"Untuk menentukan jumlah pekerja yang dibutuhkan";i:2;s:34:"Untuk menghitung harga jual minyak";i:3;s:42:"Untuk memprediksi cuaca di lokasi lapangan";}','','Karena mempengaruhi pola aliran dan efisiensi sapuan','Why is the determination of reservoir heterogeneity crucial in EOR planning?','a:4:{i:0;s:53:"Because it affects flow patterns and sweep efficiency";i:1;s:41:"To determine the number of workers needed";i:2;s:34:"To calculate the oil selling price";i:3;s:36:"To predict weather at the field site";}','Because it affects flow patterns and sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000590','Apa tanggung jawab utama tim HSE dalam proyek EOR yang menggunakan bahan kimia berbahaya?','option','PFC000000012','Final Test','a:4:{i:0;s:52:"Memastikan prosedur penanganan dan mitigasi tumpahan";i:1;s:39:"Menghitung keuntungan harian perusahaan";i:2;s:33:"Meningkatkan laju produksi minyak";i:3;s:34:"Mempercepat pengiriman bahan kimia";}','','Memastikan prosedur penanganan dan mitigasi tumpahan','What is the main responsibility of the HSE team in EOR projects using hazardous chemicals?','a:4:{i:0;s:49:"Ensuring handling procedures and spill mitigation";i:1;s:33:"Calculating daily company profits";i:2;s:31:"Increasing oil production rates";i:3;s:29:"Expediting chemical shipments";}','Ensuring handling procedures and spill mitigation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000591','Manakah yang merupakan tantangan utama dalam transisi dari pilot EOR ke skala penuh?','option','PFC000000012','Final Test','a:4:{i:0;s:45:"Skalabilitas fasilitas permukaan dan logistik";i:1;s:25:"Ketersediaan data geologi";i:2;s:24:"Kurangnya minat investor";i:3;s:25:"Penurunan harga teknologi";}','','Skalabilitas fasilitas permukaan dan logistik','Which is the main challenge in transitioning from an EOR pilot to full-field scale?','a:4:{i:0;s:47:"Scalability of surface facilities and logistics";i:1;s:31:"Availability of geological data";i:2;s:25:"Lack of investor interest";i:3;s:29:"Decrease in technology prices";}','Scalability of surface facilities and logistics','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000592','Apa yang dimaksud dengan ''sensitivity analysis'' dalam evaluasi ekonomi EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:54:"Menguji pengaruh perubahan variabel input terhadap NPV";i:1;s:37:"Mengukur tingkat kebahagiaan karyawan";i:2;s:31:"Analisis komposisi kimia minyak";i:3;s:34:"Uji ketahanan alat di laboratorium";}','','Menguji pengaruh perubahan variabel input terhadap NPV','What is meant by ''sensitivity analysis'' in EOR economic evaluation?','a:4:{i:0;s:51:"Testing the impact of input variable changes on NPV";i:1;s:34:"Measuring employee happiness level";i:2;s:36:"Analysis of oil chemical composition";i:3;s:36:"Laboratory equipment durability test";}','Testing the impact of input variable changes on NPV','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000593','Faktor apa yang dapat membatalkan keberhasilan proyek EOR secara teknis?','multi','PFC000000012','Final Test','a:4:{i:0;s:48:"Ketidakmampuan menjaga viskositas fluida injeksi";i:1;s:51:"Adanya jalur aliran pintas (channelling) yang parah";i:2;s:27:"Kenaikan harga minyak dunia";i:3;s:29:"Kesalahan desain pola injeksi";}','','a:3:{i:0;s:48:"Ketidakmampuan menjaga viskositas fluida injeksi";i:1;s:51:"Adanya jalur aliran pintas (channelling) yang parah";i:2;s:29:"Kesalahan desain pola injeksi";}','Which factors can technically invalidate the success of an EOR project?','a:4:{i:0;s:47:"Inability to maintain injection fluid viscosity";i:1;s:34:"Presence of severe flow channeling";i:2;s:24:"Rise in world oil prices";i:3;s:31:"Injection pattern design errors";}','a:3:{i:0;s:47:"Inability to maintain injection fluid viscosity";i:1;s:34:"Presence of severe flow channeling";i:2;s:31:"Injection pattern design errors";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000594','Dalam perencanaan EOR, apa kegunaan utama dari simulasi reservoir?','option','PFC000000012','Final Test','a:4:{i:0;s:53:"Memprediksi performa reservoir dan optimasi perolehan";i:1;s:53:"Mengukur kedalaman sumurusi administrasi kantor pusat";i:2;s:34:"Mempromosikan perusahaan ke publik";i:3;s:24:"Mengganti peran geologis";}','','Memprediksi performa reservoir dan optimasi perolehan','In EOR planning, what is the primary use of reservoir simulation?','a:4:{i:0;s:58:"Predicting reservoir performance and recovery optimization";i:1;s:35:"Handling head office administration";i:2;s:35:"Promoting the company to the public";i:3;s:30:"Replacing the geologist''s role";}','Predicting reservoir performance and recovery optimization','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000595','Apa yang dimaksud dengan *CapEx* dalam anggaran proyek EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:41:"Biaya modal untuk fasilitas dan peralatan";i:1;s:24:"Biaya operasional harian";i:2;s:28:"Pajak penghasilan perusahaan";i:3;s:22:"Biaya perjalanan dinas";}','','Biaya modal untuk fasilitas dan peralatan','What is meant by *CapEx* in EOR project budgets?','a:4:{i:0;s:48:"Capital expenditure for facilities and equipment";i:1;s:24:"Daily operating expenses";i:2;s:20:"Corporate income tax";i:3;s:24:"Business travel expenses";}','Capital expenditure for facilities and equipment','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000596','Mengapa pemilihan metode EOR harus disesuaikan dengan karakteristik reservoir?','option','PFC000000012','Final Test','a:4:{i:0;s:57:"Karena setiap metode memiliki batasan teknis yang berbeda";i:1;s:50:"Agar terlihat lebih canggih di mata pemegang saham";i:2;s:39:"Karena aturan pemerintah selalu berubah";i:3;s:45:"Agar tidak perlu melakukan studi laboratorium";}','','Karena setiap metode memiliki batasan teknis yang berbeda','Why must the choice of EOR method be tailored to reservoir characteristics?','a:4:{i:0;s:55:"Because each method has different technical limitations";i:1;s:54:"To look more sophisticated in the eyes of shareholders";i:2;s:44:"Because government regulations always change";i:3;s:40:"So that no laboratory studies are needed";}','Because each method has different technical limitations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000597','Apa risiko dari ''poor sweep efficiency'' dalam proyek EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:42:"Banyak minyak yang tertinggal di reservoir";i:1;s:33:"Produksi air yang terlalu sedikit";i:2;s:40:"Tekanan reservoir menjadi terlalu tinggi";i:3;s:25:"Kerusakan mesin kompresor";}','','Banyak minyak yang tertinggal di reservoir','What is the risk of ''poor sweep efficiency'' in an EOR project?','a:4:{i:0;s:44:"A lot of oil is left behind in the reservoir";i:1;s:27:"Too little water production";i:2;s:35:"Reservoir pressure becomes too high";i:3;s:25:"Compressor machine damage";}','A lot of oil is left behind in the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000598','Mengapa keterlibatan pemangku kepentingan (stakeholders) penting dalam proyek EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:46:"Untuk memastikan dukungan sosial dan perizinan";i:1;s:41:"Untuk menambah jumlah teknisi di lapangan";i:2;s:38:"Untuk mengurangi biaya produksi minyak";i:3;s:34:"Untuk mengubah hukum termodinamika";}','','Untuk memastikan dukungan sosial dan perizinan','Why is stakeholder involvement important in EOR projects?','a:4:{i:0;s:36:"To ensure social support and permits";i:1;s:50:"To increase the number of technicians in the field";i:2;s:30:"To reduce oil production costs";i:3;s:36:"To change the laws of thermodynamics";}','To ensure social support and permits','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000599','Apa peran data laboratorium dalam tahap perencanaan EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:32:"Validasi interaksi fluida-batuan";i:1;s:31:"Menggantikan kebutuhan simulasi";i:2;s:28:"Mengurangi harga jual minyak";i:3;s:33:"Menentukan lokasi kantor lapangan";}','','Validasi interaksi fluida-batuan','What is the role of laboratory data in the EOR planning phase?','a:4:{i:0;s:37:"Validation of fluid-rock interactions";i:1;s:33:"Replacing the need for simulation";i:2;s:26:"Reducing oil selling price";i:3;s:34:"Determining field office locations";}','Validation of fluid-rock interactions','2026-09-23 02:08:17','2026-09-23 02:08:17');
